/* Entrepreneurship: three practice questions plus one examination-only item
 * per teaching topic. Practice content is retained with targeted corrections.
 * Jurisdiction-specific legal and tax requirements must be checked locally. */
(function () {
  if (typeof window === 'undefined') return;
  var DATA = [
    {"key":"M1:Welcome to the Program","rows":[{"q":"What will you have built by the end of the program?","opts":["A validated idea, business model, financial plan and business plan","A completed examination paper","A registered company only","A portfolio of case studies"],"correct":0,"exp":"The program is built around producing the documents and evidence a real business needs."},{"q":"What do you need to start this course?","opts":["Startup capital of at least $500","A problem worth solving and people you can talk to","An existing registered business","A university degree"],"correct":1,"exp":"The early work is problem identification and customer conversation, neither of which needs capital."},{"q":"Which pair of risks should a founder assess while developing a startup?","opts":["Poor products and bad locations","Competition and regulation","Building something nobody wanted, and running out of cash","Weak branding and slow websites"],"correct":2,"exp":"Demand and cash availability are important risks to test and manage; this is not a ranking of all causes of failure."},{"q":"A learner finishes the startup videos but has no customer evidence. What should they produce next?","opts":["A claim of guaranteed success","A larger graduation graphic","A list of watched minutes","A documented test with prospective customers"],"correct":3,"exp":"Progress should include evidence that concepts can be applied."}]},
    {"key":"M1:How to Study This Course","rows":[{"q":"What is the most important habit in this course?","opts":["Memorising the frameworks","Completing quizzes quickly","Reading each lesson twice","Talking to potential customers regularly"],"correct":3,"exp":"Real customer conversations produce the evidence every later module depends on."},{"q":"When should you start your business plan document?","opts":["From the beginning, growing it as you go","Once funding is secured","In Module 16","After graduation"],"correct":0,"exp":"The plan is assembled from work done throughout, not written from memory at the end."},{"q":"What does it mean if your idea changes during the course?","opts":["You should restart the course","You are responding to evidence, which is progress","You have failed to commit","You chose badly at the start"],"correct":1,"exp":"Changing direction because of what customers told you is the process working correctly."},{"q":"A learner keeps changing several assumptions at once and cannot explain the results. What would improve learning?","opts":["Only watch the same video again","Delete unsuccessful experiments","Choose the most popular idea without testing","Record the hypothesis, test and resulting evidence"],"correct":3,"exp":"A clear experiment record connects actions with what was learned."}]},
    {"key":"M1:What is Entrepreneurship?","rows":[{"q":"What are the three elements of entrepreneurship?","opts":["An idea, a licence and a loan","Innovation, technology and scale","An unmet need, assembled resources, and personal risk","Capital, staff and premises"],"correct":2,"exp":"All three must be present; the risk is what distinguishes it from employment."},{"q":"What distinguishes an entrepreneur from an employee doing the same work?","opts":["Having more skills","Owning premises","Working longer hours","Bearing the risk personally, and owning the upside"],"correct":3,"exp":"An employee is paid regardless of outcome; an entrepreneur's return depends on success."},{"q":"Is innovation required for entrepreneurship?","opts":["No &mdash; a well-run ordinary business meeting a real need qualifies","Only for businesses seeking investment","Yes, always","Only in technology businesses"],"correct":0,"exp":"Meeting an unmet need well is entrepreneurship whether or not the method is novel."},{"q":"A founder sees an unmet need but has no delivery plan. What must be developed?","opts":["Only a memorable business name","Only a motivational slogan","A practical way to organise resources and create value","Only an office decoration plan"],"correct":2,"exp":"Entrepreneurship combines a need with organised action and resources."}]},
    {"key":"M1:What is a Startup?","rows":[{"q":"What is a startup searching for?","opts":["A physical location","A repeatable, scalable business model","A larger customer base","Cheaper suppliers"],"correct":1,"exp":"A startup is running experiments to discover a model it does not yet have."},{"q":"What does scalable mean?","opts":["The product can be exported","The business can hire more staff","Revenue can grow much faster than cost","The business can open more branches"],"correct":2,"exp":"Scalability means serving many more customers without a proportional rise in cost."},{"q":"Why does the distinction matter for funding?","opts":["Startups are registered differently","Startups pay lower interest","Small businesses cannot borrow","Investors fund scalable search; banks fund predictable operation"],"correct":3,"exp":"Seeking the wrong kind of money for your business type leads to unexplained rejection."},{"q":"An early venture's customers and revenue model remain uncertain. What should it prioritise?","opts":["Testing the assumptions behind a repeatable business","Scaling an untested model immediately","Treating a forecast as proven demand","Assuming every new business grows identically"],"correct":0,"exp":"An uncertain venture needs evidence before expanding its model."}]},
    {"key":"M1:Entrepreneur vs. Business Owner","rows":[{"q":"What does an entrepreneur primarily spend time on?","opts":["Discovering whether a need and a solution exist","Managing stock and staff","Collecting payments","Maintaining premises"],"correct":0,"exp":"The entrepreneurial role is the search and testing that precedes a working model."},{"q":"What happens to an owner who never innovates?","opts":["They become more profitable","They are eventually overtaken","They cannot register the business","They lose their licence"],"correct":1,"exp":"Markets change, and a business that never adapts is displaced by one that does."},{"q":"Why does recognising your strength matter?","opts":["It determines your tax status","It sets your salary","It tells you who to partner with or hire","It decides the business name"],"correct":2,"exp":"Matching people to the work they are good at is what makes the business function."},{"q":"Two founders use different growth ambitions and business models. How should their approaches be assessed?","opts":["Against their actual objectives and operating context","By assuming only rapid growth is legitimate","By assuming ordinary businesses create no value","Only by the size of their logos"],"correct":0,"exp":"Business approaches should be evaluated in their own context."}]},
    {"key":"M1:Types of Entrepreneurs","rows":[{"q":"Which type is largest across West Africa?","opts":["Social enterprises","Franchise operators","Scalable startups","Necessity entrepreneurship"],"correct":3,"exp":"Most businesses are started because employment is unavailable rather than to pursue growth."},{"q":"What does a scalable startup optimise for?","opts":["Growth, accepting early losses","Minimum staff","Immediate profit","Stability"],"correct":0,"exp":"Growth is prioritised over near-term profitability, usually funded by investment."},{"q":"Why can standard startup advice be harmful to a necessity entrepreneur?","opts":["It is written in English","It assumes the business can run at a loss while growing","It is too technical","It requires registration"],"correct":1,"exp":"A business that must provide household income weekly cannot sustain deliberate losses."},{"q":"A founder pursues community impact alongside commercial viability. What should the model clarify?","opts":["Why revenue is automatically unnecessary","Why all social ventures need identical funding","Only the founder's personal story","How impact and financial sustainability will be achieved"],"correct":3,"exp":"Impact goals still require a workable operating model."}]},
    {"key":"M1:Startup Success Stories","rows":[{"q":"What is survivorship bias?","opts":["Studying only local examples","Preferring older businesses","Only hearing about businesses that succeeded, not those that failed doing the same","Believing new businesses fail quickly"],"correct":2,"exp":"The failures are invisible, so behaviours common to both look like causes of success."},{"q":"What part of a success story is most reliable to learn from?","opts":["The founder's daily routine","The company's current valuation","Its marketing slogans","What problem it solved and for whom"],"correct":3,"exp":"The problem-solution fit transfers; the surrounding tactics usually do not."},{"q":"Why are failure stories more instructive?","opts":["They reveal the mistakes that success stories hide","They are easier to verify","They are more common","They are shorter"],"correct":0,"exp":"Failures show what actually went wrong, which survivorship bias removes from success accounts."},{"q":"A founder copies a success story without comparing its market conditions. What is missing?","opts":["A larger photograph of the founder","A matching company name","An identical office layout","Analysis of whether the example applies to the current context"],"correct":3,"exp":"Lessons from other ventures need context-sensitive evaluation."}]},
    {"key":"M1:Course Roadmap","rows":[{"q":"Which stage determines whether the rest is worth doing?","opts":["Foundation","Discovery","Resourcing","Launch"],"correct":1,"exp":"Finding a real problem and validating it establishes whether there is a business at all."},{"q":"Why does finance come before funding in the program?","opts":["Lenders require it by law","Funding is optional","You must know your numbers before asking anyone for money","Finance is easier"],"correct":2,"exp":"Without your own financial picture you cannot say how much you need or how it will be repaid."},{"q":"Why does legal registration come after validation?","opts":["Regulations require validation first","Registration is expensive","It takes a long time","So you do not register a business you then abandon"],"correct":3,"exp":"Registering before knowing whether the business works wastes money and effort."},{"q":"A learner reaches the launch module with no research or financial assumptions recorded. What should be revisited?","opts":["Only the certificate layout","Only the video playback speed","Only a launch-day slogan","The earlier evidence and planning milestones"],"correct":3,"exp":"Later decisions depend on the evidence developed earlier."}]},
    {"key":"M2:Developing an Entrepreneurial Mindset","rows":[{"q":"What is the central habit of an entrepreneurial mindset?","opts":["Treating beliefs as assumptions to be tested","Working longer hours than competitors","Defending your idea against criticism","Raising capital early"],"correct":0,"exp":"Testing rather than assuming is what prevents building something nobody wants."},{"q":"What is the entrepreneurial response to uncertainty?","opts":["Research until certain","Design the cheapest test that would settle the question","Commit fully and adapt later","Wait for a clearer market"],"correct":1,"exp":"Cheap experiments resolve uncertainty faster and at far less cost than either extreme."},{"q":"Why separate the idea from yourself?","opts":["To protect your reputation","To allow others to own it","So evidence against it is information rather than insult","To make it easier to sell"],"correct":2,"exp":"Founders who identify with an idea cannot evaluate evidence about it honestly."},{"q":"An experiment disproves a founder's favourite assumption. What response supports entrepreneurial learning?","opts":["Hide the result from the team","Repeat the claim as a certainty","Revise the assumption and plan the next test","Abandon all future evidence gathering"],"correct":2,"exp":"An evidence-led mindset adapts when assumptions fail."}]},
    {"key":"M2:Creativity and Innovation","rows":[{"q":"What is the difference between creativity and innovation?","opts":["They are the same","Creativity is technical; innovation is artistic","Innovation happens first","Creativity generates ideas; innovation turns one into something adopted"],"correct":3,"exp":"An idea only becomes an innovation when people actually use it."},{"q":"Why should generating and judging be separated?","opts":["Evaluating while producing reduces the number of ideas generated","Judging requires other people","Generating is more important","Judging takes longer"],"correct":0,"exp":"Criticism during generation suppresses output, and volume is what produces good ideas."},{"q":"What is most innovation actually made of?","opts":["Improved technology","Recombination of things that already exist","Scientific discovery","Entirely new inventions"],"correct":1,"exp":"Most innovations combine existing elements in a new arrangement rather than inventing from nothing."},{"q":"A team generates many ideas but implements none. What connects creativity to innovation?","opts":["Only collecting more unrelated slogans","Only renaming the brainstorming session","Testing and applying a useful idea","Assuming novelty guarantees demand"],"correct":2,"exp":"Innovation requires practical application and evaluation."}]},
    {"key":"M2:Identifying Opportunities","rows":[{"q":"What is an opportunity, as distinct from an idea?","opts":["A funding offer","A market segment","The gap between what people need and what is available","A proposed product"],"correct":2,"exp":"The idea is your solution; the opportunity is the gap the solution would close."},{"q":"Why is a workaround strong evidence of a need?","opts":["Workarounds are easy to copy","They indicate a large market","Workarounds are profitable","People improvising a poor solution shows they need it enough to act"],"correct":3,"exp":"Effort spent on an improvised fix demonstrates real demand better than any stated preference."},{"q":"Why is unreliability an opportunity?","opts":["An existing service delivered dependably is often enough to win customers","Regulators intervene","Unreliable businesses are cheap to buy","It reduces competition permanently"],"correct":0,"exp":"Where demand is proven but delivery is poor, reliability alone can be the whole offer."},{"q":"A recurring customer frustration appears in several interviews. What should the founder investigate?","opts":["Only whether the idea sounds impressive","Only the competitor's logo","Whether the founder can ignore other evidence","Its frequency, impact and willingness to adopt a solution"],"correct":3,"exp":"An opportunity needs evidence of a meaningful solvable need."}]},
    {"key":"M2:Solving Real Problems","rows":[{"q":"What is the strongest test of whether a problem is real?","opts":["Whether the market is large","Whether people are already doing something about it","Whether competitors exist","Whether people say it is important"],"correct":1,"exp":"Existing effort or spending demonstrates that the problem hurts enough to act on."},{"q":"What does 'nice to have' usually mean?","opts":["The price is too high","The customer will pay a premium","Nobody will pay for it","The product needs improvement"],"correct":2,"exp":"It is a polite refusal that founders frequently mistake for encouragement."},{"q":"A large market has no existing solutions. What should you ask?","opts":["How quickly can I launch?","How much funding do I need?","Which competitor should I copy?","Why has nobody tried, since the reason usually matters"],"correct":3,"exp":"An untouched large market usually has a structural reason that will affect you too."},{"q":"A solution is technically impressive but does not address the customer's difficulty. What should change?","opts":["Reframe the solution around the validated problem","Add more unrelated features","Increase the marketing claim","Avoid further customer conversations"],"correct":0,"exp":"Useful solutions must address the actual customer problem."}]},
    {"key":"M2:Growth Mindset","rows":[{"q":"How does a growth mindset interpret a failed attempt?","opts":["As information about the approach used","As evidence of fixed ability","As proof the market is wrong","As a reason to stop"],"correct":0,"exp":"Attributing failure to method rather than capacity keeps improvement possible."},{"q":"What is the difference between persistence and stubbornness?","opts":["Persistence takes longer","Persist with the goal, change the method; stubbornness repeats the method","Stubbornness is more effective","They are the same"],"correct":1,"exp":"Continuing with a method that has been shown not to work is not determination."},{"q":"Why seek feedback from people likely to disagree?","opts":["They are more experienced","They respond faster","They reveal problems that supporters will not mention","They may become customers"],"correct":2,"exp":"Agreement teaches nothing; disagreement surfaces the weaknesses you cannot see."},{"q":"A founder struggles with bookkeeping for the first time. What reflects a growth mindset?","opts":["Conclude improvement is impossible","Hide all errors indefinitely","Seek feedback and practise the missing skill","Assume confidence replaces competence"],"correct":2,"exp":"Skills can improve through deliberate practice and support."}]},
    {"key":"M2:Leadership Skills","rows":[{"q":"What do early founders lead with, lacking money and authority?","opts":["Charisma","Equity promises","Long working hours","Clarity and reliability"],"correct":3,"exp":"Explaining plainly and doing what you said are available from the start and cost nothing."},{"q":"How should a founder handle a mistake by a team member?","opts":["Fix the system that allowed it","Reduce their responsibility","Take over the task permanently","Assign blame clearly"],"correct":0,"exp":"Blame discourages disclosure; fixing the system prevents recurrence."},{"q":"What should a founder do before paying themselves?","opts":["Reinvest in marketing","Pay people what was promised, on time","Register the business","Repay all loans"],"correct":1,"exp":"Reliability with other people's pay is the foundation of a founder's credibility."},{"q":"A team does not understand who owns a launch task. What should its leader clarify?","opts":["Only the team's slogan","The responsibility, expected outcome and deadline","Only the leader's job title","Only the presentation colours"],"correct":1,"exp":"Leadership includes making responsibilities and expectations clear."}]},
    {"key":"M2:Decision Making","rows":[{"q":"Which decisions should be made quickly?","opts":["Ones affecting customers","Expensive ones","Reversible, low-cost ones","Ones involving partners"],"correct":2,"exp":"When being wrong is cheap and undoable, deliberation costs more than the error would."},{"q":"Why write down the reasoning behind a decision?","opts":["To speed up future decisions","To share with investors","To satisfy record-keeping rules","So the decision can later be judged separately from its outcome"],"correct":3,"exp":"Outcomes are affected by luck; only the recorded reasoning shows whether the decision was sound."},{"q":"What should be done before an irreversible, expensive decision?","opts":["Run a small test where one is possible","Seek more opinions","Delay until certain","Reduce the cost"],"correct":0,"exp":"A cheap test converts an irreversible commitment into an informed one."},{"q":"A founder must choose between two suppliers under uncertainty. What supports a defensible decision?","opts":["Only the most confident salesperson","Only the cheapest headline price","Explicit criteria, available evidence and recognised trade-offs","Ignoring delivery risk"],"correct":2,"exp":"Decisions improve when criteria and uncertainty are made explicit."}]},
    {"key":"M2:Critical Thinking","rows":[{"q":"What is confirmation bias?","opts":["Seeking expert opinion","Noticing supporting evidence and overlooking the rest","Repeating an experiment","Confirming an order before delivery"],"correct":1,"exp":"It causes founders to accumulate apparent support while ignoring contrary signals."},{"q":"Why is stated intention weaker evidence than behaviour?","opts":["Statements cannot be recorded","People forget what they said","People often say what is polite rather than what they will do","Behaviour is easier to measure"],"correct":2,"exp":"Saying yes costs nothing, so it is a poor predictor of actual purchase."},{"q":"What question exposes a meaningless number?","opts":["How was it recorded?","Who measured it?","When was it measured?","Compared to what?"],"correct":3,"exp":"A figure only carries meaning against a baseline or an alternative."},{"q":"A market report claims enormous demand without explaining its sample. What should be questioned?","opts":["The evidence, method and relevance behind the claim","Only the report's cover design","Only its file extension","Only the author's font choice"],"correct":0,"exp":"Critical thinking examines how conclusions are supported."}]},
    {"key":"M2:Time Management","rows":[{"q":"What is time management for a founder mainly about?","opts":["Deciding which things not to do","Delegating everything","Extending working hours","Working faster"],"correct":0,"exp":"There is always more possible work than time, so selection matters more than speed."},{"q":"What is 'comfortable work'?","opts":["Work that is well paid","Work that feels productive but resolves no real uncertainty","Work delegated to others","Work done at home"],"correct":1,"exp":"Logo design and website polish feel like progress while leaving the key questions untested."},{"q":"Where should a founder's best hours go early on?","opts":["Designing branding","Seeking funding","Reducing the biggest current uncertainty, usually by talking to customers","Building the product"],"correct":2,"exp":"The largest unknown early is whether anyone wants the product, and only customers can answer that."},{"q":"A founder spends every day on low-impact tasks while an urgent launch dependency waits. What should improve?","opts":["Only the length of the to-do list","Only the calendar's colour theme","Working on tasks solely in alphabetical order","Prioritisation based on importance and dependencies"],"correct":3,"exp":"Time should be allocated to the work that enables meaningful progress."}]},
    {"key":"M2:Personal Productivity","rows":[{"q":"Why does a founder need a system rather than motivation?","opts":["Systems impress investors","Motivation cannot be measured","Systems are faster","Motivation is unreliable while a system is not"],"correct":3,"exp":"Nobody assigns a founder's work, so consistency must come from structure rather than feeling."},{"q":"What are the three parts of a workable system?","opts":["One capture place, a weekly review, and a short daily list","A calendar, an assistant and a deadline","Goals, targets and reports","Software, hardware and training"],"correct":0,"exp":"Capture, review and a realistic daily list together keep commitments from being dropped."},{"q":"What is the difference between urgent and important?","opts":["Important tasks have deadlines","Urgency is often someone else's priority, not yours","They are the same in a small business","Urgent tasks are larger"],"correct":1,"exp":"Responding to urgency alone means working on other people's agendas rather than your own."},{"q":"Constant interruptions prevent a founder from completing focused work. What adjustment is useful?","opts":["Protected focus periods with deliberate communication windows","Keeping every alert active continuously","Starting more tasks simultaneously","Measuring success only by hours at the desk"],"correct":0,"exp":"Productivity depends on useful completed work and managed attention."}]},
    {"key":"M3:Finding Business Ideas","rows":[{"q":"Why does existing knowledge of a field matter?","opts":["It makes funding easier","It shortens registration","It lets you judge whether the problem is real, who the customer is and what delivery costs","It reduces competition"],"correct":2,"exp":"Domain knowledge lets you evaluate an idea quickly instead of learning the basics first."},{"q":"What is a productive question to ask people?","opts":["What do you think of this idea?","How much would you pay?","Would you buy my product?","What wasted your time or money this week?"],"correct":3,"exp":"Asking about actual recent experience surfaces real problems rather than opinions on your idea."},{"q":"When looking at something that exists elsewhere but not locally, what should you ask?","opts":["Why is it not here already?","What is its brand name?","How fast can I copy it?","Who funded it?"],"correct":0,"exp":"The reason for its absence usually reveals a constraint that will apply to you too."},{"q":"A founder lists fashionable products without identifying customers. What should be added?","opts":["Only more fashionable product names","Specific customer needs and feasible ways to serve them","Only a larger idea spreadsheet","Only an investor contact list"],"correct":1,"exp":"Business ideas need a defined customer and useful value."}]},
    {"key":"M3:Problem Identification","rows":[{"q":"What should a problem statement contain?","opts":["A description of your product","Who has it, what it is, how often, and what it costs them","The size of the market","Your competitive advantage"],"correct":1,"exp":"These four elements make the statement specific enough to be checked."},{"q":"Why is 'they do not have an app' a poor problem statement?","opts":["Apps are expensive","Not everyone has a phone","It describes a missing product rather than an observable problem","It is too technical"],"correct":2,"exp":"Defining the problem as the absence of your solution makes it impossible to disprove."},{"q":"What is wrong with 'small businesses struggle with finances'?","opts":["It is too negative","It is too long","Finances are not a real problem","It names no specific person, mechanism or cost"],"correct":3,"exp":"Without specificity there is nothing concrete to test or to build against."},{"q":"Interviewees describe losing time but the founder immediately assumes they need an app. What should be clarified first?","opts":["The app's colour scheme","The cheapest domain name","The underlying difficulty and current workarounds","The number of proposed screens"],"correct":2,"exp":"Problem understanding should precede a preferred solution."}]},
    {"key":"M3:Brainstorming Techniques","rows":[{"q":"What rule makes brainstorming work?","opts":["Deferring judgement while generating","Involving senior people","Setting a time limit","Recording everything"],"correct":0,"exp":"Criticism during generation collapses output and pushes people towards safe suggestions."},{"q":"Why continue past the first several ideas?","opts":["To fill the session","Because early ideas are the obvious ones everyone has","To involve more people","Because later ideas are cheaper"],"correct":1,"exp":"Distinctive options tend to emerge only after the obvious ones are exhausted."},{"q":"Why write ideas individually before sharing?","opts":["It is faster","It avoids arguments","Groups converge too early on the first suggestion made","It produces better handwriting"],"correct":2,"exp":"Once a suggestion is voiced, the group anchors on it and variety drops."},{"q":"A brainstorming session rejects every unusual idea before recording it. What process change would help?","opts":["Require an immediate financial forecast for every thought","Allow only the leader to speak","Separate idea generation from later evaluation","Rank ideas before anyone contributes"],"correct":2,"exp":"Separating generation and judgement supports broader exploration."}]},
    {"key":"M3:Market Gap Analysis","rows":[{"q":"What counts as competition?","opts":["Only larger companies","Only businesses in the same location","Only businesses selling the same product","Whatever the customer does now, including improvising or doing nothing"],"correct":3,"exp":"The alternative you must beat is the customer's current behaviour, whatever form it takes."},{"q":"Which gap types are most commonly overlooked?","opts":["Time and location gaps","Segment gaps","Price gaps","Quality gaps"],"correct":0,"exp":"Serving the same customers at a different hour or place is often the simplest available gap."},{"q":"What does 'there is no competition' usually mean?","opts":["The founder has an advantage","The market has been surveyed carelessly, or nobody wants it","The market is new","The idea is protected"],"correct":1,"exp":"Genuine absence of any alternative is rare and usually signals absent demand."},{"q":"A founder sees no direct competitor and declares a market gap proven. What else should be checked?","opts":["Demand and the alternatives customers already use","Only whether the company name is available","Only the founder's enthusiasm","Only the number of social followers"],"correct":0,"exp":"Absence of a visible competitor does not establish demand."}]},
    {"key":"M3:Design Thinking","rows":[{"q":"What are the five stages of design thinking?","opts":["Research, design, fund, produce, sell","Observe, decide, act, review, repeat","Empathise, define, ideate, prototype, test","Plan, build, launch, measure, grow"],"correct":2,"exp":"The sequence moves from understanding the user to testing a cheap version with them."},{"q":"Why observe rather than only ask?","opts":["Asking is impolite","Observation requires no permission","Observation is faster","People often cannot describe what they actually do"],"correct":3,"exp":"Watching reveals constraints and workarounds people do not think to mention."},{"q":"What fidelity should a first prototype have?","opts":["The lowest that can still be tested","Whatever the budget allows","Close to the final product","Fully functional"],"correct":0,"exp":"A cheap prototype answers the question at a fraction of the cost, and can be discarded freely."},{"q":"A prototype test reveals users misunderstood the proposed service. What should follow?","opts":["Use the feedback to revise the problem framing or prototype","Declare the users wrong","Launch unchanged because effort was spent","Hide the test notes"],"correct":0,"exp":"An iterative design process learns from user interaction."}]},
    {"key":"M3:Customer Discovery","rows":[{"q":"What is the one rule of customer discovery?","opts":["Record every conversation on video","Gather information, do not sell","Always mention the price","Interview only decision makers"],"correct":1,"exp":"Persuading stops the flow of honest information, which is the point of the exercise."},{"q":"Which kind of question produces useful answers?","opts":["Do you like this idea?","Would you buy this?","What did you do the last time this happened?","How much would you pay?"],"correct":2,"exp":"Past behaviour is evidence; hypothetical future behaviour is a polite guess."},{"q":"Why avoid interviewing friends?","opts":["They may copy the idea","They are too busy","They lack relevant experience","They protect your feelings rather than telling you the truth"],"correct":3,"exp":"Friendly respondents systematically overstate interest, producing false confidence."},{"q":"A founder pitches throughout every discovery conversation. What should they do differently?","opts":["Explain more features without listening","Offer only leading yes-or-no questions","Ask about actual needs and past behaviour before promoting a solution","Seek praise from friends alone"],"correct":2,"exp":"Discovery aims to understand customers rather than obtain polite approval."}]},
    {"key":"M3:Customer Interviews","rows":[{"q":"Why ask the same core questions in every interview?","opts":["So answers can be compared across interviews","To appear professional","Because regulations require consistency","To save preparation time"],"correct":0,"exp":"Consistency is what allows patterns across respondents to be identified and counted."},{"q":"What is wrong with 'Don't you find late deliveries frustrating?'","opts":["It is impolite","It is a leading question that suggests the answer","It assumes they order deliveries","It is too long"],"correct":1,"exp":"Leading questions produce agreement rather than information."},{"q":"How much should the interviewer speak?","opts":["About half the time","Most of the time, to explain the idea","Less than a quarter of the time","Only at the start and end"],"correct":2,"exp":"The purpose is to hear the respondent, so the interviewer should say very little."},{"q":"An interviewer asks whether the customer would love a hypothetical product. What is a stronger question?","opts":["Ask how impressive the founder seems","Ask whether everyone should buy it","Ask how they handled the relevant problem most recently","Ask only whether the logo is attractive"],"correct":2,"exp":"Past behaviour provides more concrete evidence than hypothetical praise."}]},
    {"key":"M3:Idea Validation","rows":[{"q":"What counts as validation?","opts":["A large number of survey responses","Interest from an investor","Enthusiastic feedback","A commitment that costs the customer something"],"correct":3,"exp":"Only evidence with a cost attached predicts actual purchasing behaviour."},{"q":"What is a concierge test?","opts":["Delivering the service manually to a few customers before building it","Hiring someone to run the business","Testing with a focus group","Offering the product free"],"correct":0,"exp":"Manual delivery proves demand and reveals the real work without any product built."},{"q":"Why should refusals be recorded?","opts":["To report to investors","Because the reasons for refusal are data about the offer","To measure market size","To follow up later"],"correct":1,"exp":"Why people decline usually explains what is wrong with the price, the offer or the target."},{"q":"Potential customers praise an idea but none accept a realistic pilot offer. What should be reconsidered?","opts":["Only the pitch's background colour","The demand, offer and price assumptions","The certainty that demand is proven","Only the founder's biography"],"correct":1,"exp":"Praise and actual purchase behaviour provide different levels of evidence."}]},
    {"key":"M3:Product-Market Fit","rows":[{"q":"What is the clearest signal of product-market fit?","opts":["Investor interest","Positive feedback","Retention &mdash; customers returning without prompting","Number of sign-ups"],"correct":2,"exp":"Repeat use is behaviour, and behaviour predicts value where opinion does not."},{"q":"Why are complaints during an outage a positive signal?","opts":["They indicate high pricing","They generate publicity","They identify technical faults","They show customers depend on the service"],"correct":3,"exp":"People only complain about losing something they had come to rely on."},{"q":"Why not scale before achieving fit?","opts":["Growth spending on a product people leave multiplies the loss","Scaling is expensive","Investors require fit first","Regulations prevent it"],"correct":0,"exp":"Acquiring more customers for a product that does not retain them wastes the acquisition cost."},{"q":"Sign-ups increase but few users return. What needs investigation before scaling?","opts":["Only the size of the signup button","Only the total follower count","The assumption that growth proves fit","Retention and whether the product delivers ongoing value"],"correct":3,"exp":"Repeated useful engagement matters when evaluating product-market fit."}]},
    {"key":"M3:Selecting the Best Business Idea","rows":[{"q":"Why set criteria before evaluating ideas?","opts":["It saves time","Otherwise you justify the idea you already preferred","Criteria are required for funding","It reduces the number of options"],"correct":1,"exp":"Choosing criteria after seeing the options allows preference to determine the result."},{"q":"Which criterion should carry the most weight?","opts":["Originality of the idea","Expected profit margin","Strength of evidence that the problem is real","Size of the potential market"],"correct":2,"exp":"Demand is the factor most often assumed and the one whose absence kills the business."},{"q":"Why prefer an idea that can start small for a first business?","opts":["Customers prefer small suppliers","Small businesses are more profitable","It avoids registration","It reduces capital at risk and gets you learning sooner"],"correct":3,"exp":"Lower capital and faster entry mean the cost of being wrong is small and the learning is fast."},{"q":"Three ideas are compared using different criteria chosen after each score. What should change?","opts":["Choose whichever has the longest name","Ignore implementation costs","Use consistent agreed criteria and evidence across candidates","Treat excitement as the only criterion"],"correct":2,"exp":"A fair comparison needs consistent decision criteria."}]},
    {"key":"M4:Introduction to Market Research","rows":[{"q":"What can market research not establish?","opts":["Whether people will actually buy something that does not yet exist","What competitors charge","How large a market is","Who the customer is"],"correct":0,"exp":"Stated intention is unreliable; only a real transaction validates demand."},{"q":"What matters more than sample size?","opts":["Number of questions","Sample relevance","Survey length","Response speed"],"correct":1,"exp":"Ten genuine potential customers tell you more than a hundred unrelated respondents."},{"q":"What should be defined before research begins?","opts":["The budget","The sample size","The decision the research will inform","The report format"],"correct":2,"exp":"Without a decision in view, research expands indefinitely and answers nothing."},{"q":"A research project collects many statistics without a business decision in mind. What should be defined?","opts":["The question and decision the research will support","Only the report's page count","Only the survey's logo","Only a list of unrelated industries"],"correct":0,"exp":"Research should be directed toward a useful decision."}]},
    {"key":"M4:Primary Research","rows":[{"q":"Which primary method is best for discovery?","opts":["Focus groups","Online polls","Surveys","Interviews and observation"],"correct":3,"exp":"Open conversation and watching reveal what you did not know to ask about."},{"q":"What are surveys most useful for?","opts":["Measuring something you already understand","Generating ideas","Discovering unknown problems","Building relationships"],"correct":0,"exp":"A survey can only capture answers to questions already thought of, so it measures rather than discovers."},{"q":"Why observe rather than rely on description?","opts":["It requires no permission","People describe their own behaviour inaccurately","Observation is cheaper","It is more polite"],"correct":1,"exp":"What people say they do and what they actually do frequently differ."},{"q":"A founder needs to understand a workflow nobody has documented. Which evidence would help most directly?","opts":["Only unrelated national headlines","Only a competitor's slogan","Only the founder's assumptions","Observation and interviews with actual users"],"correct":3,"exp":"Primary evidence can reveal context-specific behaviour."}]},
    {"key":"M4:Secondary Research","rows":[{"q":"What is the main limitation of secondary data?","opts":["It cannot be cited","It is expensive","It was collected for someone else's purpose and may not match yours","It is always inaccurate"],"correct":2,"exp":"Purpose, date and geography may all differ from your situation."},{"q":"Why can national averages mislead a local business?","opts":["They exclude small businesses","They are calculated incorrectly","They are published late","They may bear no relation to one town or neighbourhood"],"correct":3,"exp":"Averaging across a whole country conceals wide local variation."},{"q":"How should secondary research be used?","opts":["To frame questions that primary research then answers","To replace customer conversations","To set prices directly","To satisfy investors only"],"correct":0,"exp":"It provides context cheaply, but the specific answers must come from your own market."},{"q":"A market estimate comes from an old report covering another country. What should be assessed?","opts":["Its date, method and applicability to the target market","Only whether it supports the desired conclusion","Only the report's font","Only its download count"],"correct":0,"exp":"Existing research needs relevance and quality checks."}]},
    {"key":"M4:Customer Personas","rows":[{"q":"What should a persona be based on?","opts":["Competitor customer lists","Real interviews with actual people","The founder's assumptions","Industry statistics"],"correct":1,"exp":"A persona invented without interviews is a guess wearing a name, not a tool grounded in evidence."},{"q":"What is the value of one well-built persona over five vague ones?","opts":["It requires no interviews","It takes less time to write","It stays specific enough to actually test decisions against","It covers a larger market"],"correct":2,"exp":"Specificity is what makes a persona useful; vague coverage of everyone tests nothing."},{"q":"How should a persona change over time?","opts":["It should be replaced every month regardless of evidence","It should be simplified over time","It should never change once written","It should be revised as more interviews add evidence"],"correct":3,"exp":"New interviews are new evidence, and the persona should reflect what is actually learned."},{"q":"A persona contains invented preferences with no research behind them. What should improve?","opts":["Only the fictional name","Its grounding in customer evidence and useful behavioural patterns","Only the portrait illustration","Only the number of hobbies"],"correct":1,"exp":"Personas should summarise evidence rather than decorate assumptions."}]},
    {"key":"M4:Target Market","rows":[{"q":"Why is 'everyone' not a usable target market?","opts":["It gives no way to focus limited resources or craft one message","It is illegal to target everyone","Everyone already has a preferred provider","It is too expensive to reach everyone"],"correct":0,"exp":"Without a defined focus, marketing spend and product decisions have nothing to aim at."},{"q":"Why start with a narrow target market?","opts":["Narrow markets are always larger","It is specific enough to learn from and serve well before expanding","Regulations require narrow targeting","Narrow markets need no marketing"],"correct":1,"exp":"A focused starting segment can be understood and reached; expansion follows once it is proven."},{"q":"What must be checked before committing to a narrow segment?","opts":["That the segment is the cheapest to reach","That competitors are absent","That the segment is large enough to sustain the business","That the segment has no existing habits"],"correct":2,"exp":"A segment defined too narrowly may not contain enough customers to build a viable business."},{"q":"A venture says its target market is everyone. What should it define instead?","opts":["A specific reachable segment with a relevant need","Only the world's total population","Only the founder's age group","Only the busiest advertising channel"],"correct":0,"exp":"A focused target helps shape a usable offer and acquisition approach."}]},
    {"key":"M4:Industry Analysis","rows":[{"q":"What can happen to a good business idea in a shrinking industry?","opts":["Shrinking industries have no competition","It becomes exempt from regulation","It automatically succeeds","It can still fail despite good execution"],"correct":3,"exp":"Industry-level headwinds can overwhelm even a well-run individual business."},{"q":"What do low barriers to entry mean for an industry?","opts":["Constant new competition can be expected","Prices are always higher","The industry is shrinking","Fewer regulations always apply"],"correct":0,"exp":"Easy entry means competitors can appear quickly whenever the market looks attractive."},{"q":"Why check for regulatory requirements early?","opts":["To avoid needing a business model","To avoid committing capital before understanding legal obligations","Because all industries are equally regulated","Because regulation guarantees success"],"correct":1,"exp":"Discovering a costly regulatory requirement after investing is far more damaging than checking first."},{"q":"An industry report lists market size but ignores regulation and supplier power. What is missing?","opts":["Factors affecting how the industry operates and competes","Only more decorative charts","Only the report's cover title","Only the founder's contact details"],"correct":0,"exp":"Industry analysis should examine conditions that shape participation."}]},
    {"key":"M4:Competitor Analysis","rows":[{"q":"What counts as a competitor in this analysis?","opts":["Only businesses in the same city","Only companies with an identical product","Direct, indirect and informal alternatives, including doing nothing","Only businesses larger than yours"],"correct":2,"exp":"Any existing way the customer meets the need today is part of the competitive picture."},{"q":"What is the purpose of reading competitor reviews and complaints?","opts":["To calculate their revenue","To report them to regulators","To copy their marketing language","To find specific weaknesses that represent an opening"],"correct":3,"exp":"Complaints reveal exactly where an existing offer falls short of what customers want."},{"q":"What should competitor analysis lead to?","opts":["Identifying where competitors are weak or absent","Avoiding the market entirely","Matching every competitor's price","Copying the strongest competitor exactly"],"correct":0,"exp":"The value is in finding an opening, not in imitating what already exists."},{"q":"A founder compares only direct rivals and ignores customers' manual workaround. What should be included?","opts":["Only businesses with identical logos","Substitutes and existing ways of solving the problem","Only firms in the same building","Only the newest startup"],"correct":1,"exp":"Customers can choose alternatives outside the direct product category."}]},
    {"key":"M4:SWOT Analysis","rows":[{"q":"Which two SWOT elements are internal to the business?","opts":["Weaknesses and threats","Strengths and weaknesses","Opportunities and threats","Strengths and opportunities"],"correct":1,"exp":"Strengths and weaknesses describe the business itself; opportunities and threats describe its environment."},{"q":"Why is honesty about weaknesses the most important part of a SWOT?","opts":["Weaknesses are easiest to write","Weaknesses are required by investors","They are where the real planning and risk response happens","Strengths are always obvious"],"correct":2,"exp":"A SWOT that avoids weaknesses produces no useful plan for addressing real risk."},{"q":"What should follow identifying a weakness?","opts":["Ignoring it until it becomes a problem","Comparing it to a competitor's strength only","Removing it from the list","Considering what could be done about it"],"correct":3,"exp":"An identified weakness is only useful if it leads to a response."},{"q":"A team labels unreliable internal processes as an external threat. Where does that issue normally belong?","opts":["An internal weakness","An external opportunity","An external demographic trend","A proven competitive strength"],"correct":0,"exp":"SWOT distinguishes internal capabilities from external conditions."}]},
    {"key":"M4:Market Trends","rows":[{"q":"What distinguishes a genuine trend from a fad?","opts":["A trend rests on a durable cause; a fad rests on temporary novelty","A trend lasts exactly one year","A fad is always more profitable","A trend is always technology-related"],"correct":0,"exp":"Durability of the underlying cause is what separates a lasting shift from a passing one."},{"q":"Why be sceptical of trends defined by social media attention alone?","opts":["Social media is always inaccurate","Attention fades faster than real behaviour change","Social media cannot be measured","Trends require government confirmation"],"correct":1,"exp":"Visibility on a platform does not guarantee the underlying behaviour is lasting."},{"q":"What should be checked before betting a decision on a trend?","opts":["That competitors have not noticed it","That it started this year","That it applies to your specific target customer, verified with more than one source","That it is mentioned in the news"],"correct":2,"exp":"A trend must be confirmed and shown to actually affect your customer before it justifies a decision."},{"q":"A temporary spike in interest is treated as a lasting trend. What should be examined?","opts":["The underlying drivers, duration and supporting evidence","Only the peak number","Only the chart's colour","Only a viral headline"],"correct":0,"exp":"Trend analysis should distinguish durable changes from short-lived variation."}]},
    {"key":"M4:Research Report","rows":[{"q":"What should a research report end with?","opts":["A description of the industry only","A list of competitors","A list of every interview conducted","A specific recommendation"],"correct":3,"exp":"The purpose of the research is to support a decision, and the recommendation is where that decision is stated."},{"q":"What is the common failure in research reports?","opts":["Describing findings without stating what they mean for the decision","Including too many interviews","Being too short","Including a recommendation"],"correct":0,"exp":"A report that only summarises findings without interpreting them fails to support any decision."},{"q":"Why keep the report short?","opts":["Short reports are always more accurate","So it will actually be read and acted on","Because long reports are illegal","To reduce the evidence presented"],"correct":1,"exp":"A report nobody reads to the end cannot inform the decision it was meant to support."},{"q":"A report gives a conclusion but omits limitations. What should it disclose?","opts":["The methods, sources and boundaries of the evidence","Only favourable results","Only the founder's favourite quote","Only the report's print cost"],"correct":0,"exp":"Readers need enough context to judge the strength of findings."}]},
    {"key":"M5:Business Model Basics","rows":[{"q":"What two questions define a business model?","opts":["Who the founder is, and where the business is located","How large the market is, and how fast it grows","What customers get, and how the business is paid for it","What the product costs, and who makes it"],"correct":2,"exp":"Value delivered and value captured together define the model, independent of the specific product."},{"q":"Can the same product exist under different business models?","opts":["Only software products allow this","Only physical products allow this","No, the product determines the model","Yes, the same product can be sold, rented, or monetised differently"],"correct":3,"exp":"How revenue is captured is a separate choice from what is offered."},{"q":"Why might a business choose recurring revenue over a larger one-time sale?","opts":["It builds predictable revenue that is valued by lenders and investors","One-time sales are illegal","Recurring revenue requires no customers","Recurring revenue is always higher in total"],"correct":0,"exp":"Predictability itself has value beyond the raw revenue total, particularly when seeking financing."},{"q":"A venture explains its product but not how it sustains operations. What remains to define?","opts":["Only its logo","Only the website's colour scheme","How value is delivered, funded and captured","Only the founder's job title"],"correct":2,"exp":"A business model connects customer value with workable economics."}]},
    {"key":"M5:Business Model Canvas","rows":[{"q":"How many blocks does the Business Model Canvas have?","opts":["Four","Nine","Five","Twelve"],"correct":1,"exp":"The nine blocks together cover every essential part of how a business creates and captures value."},{"q":"What is the main value of putting the whole model on one page?","opts":["It is required by law","It looks more professional","Connections and gaps between blocks become visible","It replaces the need for customer research"],"correct":2,"exp":"Seeing all blocks together exposes mismatches, such as costly resources with no matching revenue."},{"q":"How should the canvas be treated?","opts":["As a legal filing","As a marketing brochure","As a final, unchanging document","As a working document updated as you learn"],"correct":3,"exp":"It is meant to evolve with the business's understanding of itself, not to be fixed at the start."},{"q":"A canvas is filled with guesses presented as facts. What should be distinguished?","opts":["Only long and short sentences","Only colourful and plain boxes","Validated information and assumptions requiring tests","Only the founder's preferred layout"],"correct":2,"exp":"The canvas should make uncertainty visible for learning."}]},
    {"key":"M5:Value Proposition","rows":[{"q":"What makes a value proposition strong?","opts":["Being specific and testable about the customer, problem and benefit","Length and detail","Matching a competitor's wording","Impressive-sounding language"],"correct":0,"exp":"Specificity is what allows the claim to be checked against real customer experience."},{"q":"What should a value proposition focus on?","opts":["The technical features of the product","The outcome or change for the customer","The founder's background","The size of the company"],"correct":1,"exp":"Customers buy the change in their situation, not the mechanism that produces it."},{"q":"Why should a value proposition be falsifiable?","opts":["So it satisfies legal requirements","So it can be patented","So it is specific enough that it could turn out to be wrong, and therefore testable","So it sounds more confident"],"correct":2,"exp":"A vague claim that can never be wrong also can never be validated as right."},{"q":"A value proposition lists features but not customer benefits. What should improve?","opts":["The connection to a specific customer problem and useful outcome","Only the number of technical terms","Only the slogan's rhyme","Only the product's file size"],"correct":0,"exp":"Value should explain why the offer matters to its customer."}]},
    {"key":"M5:Customer Segments","rows":[{"q":"What is more useful for segmentation than demographics alone?","opts":["Segmenting by age only","Segmenting by location only","Not segmenting at all","Segmenting by need and behaviour"],"correct":3,"exp":"Need and behaviour predict what a customer wants far better than demographic categories alone."},{"q":"When should a group be treated as two separate segments?","opts":["When they differ enough to need a different approach","Whenever there are more than ten customers","Only when they live in different areas","Never, one segment always covers everyone"],"correct":0,"exp":"Meaningfully different needs or behaviours justify treating a group as separate segments."},{"q":"What must a segment be, beyond being definable?","opts":["Profitable immediately","Reachable","Large","International"],"correct":1,"exp":"A segment you cannot actually reach with a message or channel is not practically useful."},{"q":"Two groups have different needs and buying behaviour. What should the model consider?","opts":["Assume all customers need identical treatment","Distinct segments with appropriate offers and channels","Ignore the smaller group automatically","Define segments only by the founder's preferences"],"correct":1,"exp":"Segments should reflect meaningful differences relevant to serving customers."}]},
    {"key":"M5:Customer Relationships","rows":[{"q":"What does the customer relationships block define?","opts":["The legal structure of the business","The physical location of the business","How the business interacts with customers over time","The price of the product"],"correct":2,"exp":"It covers the ongoing style of interaction, from personal service to full automation."},{"q":"What is a risk of purely personal, one-to-one service?","opts":["Customers always dislike it","It requires no cost","It is illegal in most markets","It scales poorly as the business grows"],"correct":3,"exp":"Direct personal attention to every customer becomes unsustainable past a certain size."},{"q":"What causes a common source of customer complaints in this area?","opts":["A mismatch between the relationship customers expected and what was delivered","Charging any price at all","Having any self-service option","Too much automation always"],"correct":0,"exp":"Complaints arise when the actual relationship falls short of what the customer expected going in."},{"q":"A subscription service needs ongoing use but offers no onboarding support. What relationship need is missing?","opts":["Only a larger sales banner","Only a once-off company introduction","Helping customers adopt and continue gaining value","Only more unrelated advertisements"],"correct":2,"exp":"Relationship design includes supporting successful ongoing use."}]},
    {"key":"M5:Channels","rows":[{"q":"What are channels, in this context?","opts":["The legal registration process","The paths through which customers learn about, buy, and receive support for the offer","The suppliers a business uses","The staff structure of a business"],"correct":1,"exp":"Channels cover every stage of how customers reach and are served by the business."},{"q":"What is a benefit of an owned channel?","opts":["No need for marketing","Greater reach with no effort","More control and margin","Zero cost"],"correct":2,"exp":"Direct control over the channel usually comes with a larger share of the value, at the cost of building the reach yourself."},{"q":"Why is trying many channels at once risky for a small team?","opts":["Customers dislike businesses with multiple channels","It always costs more than one channel combined","It is illegal to use multiple channels","None gets enough attention to work well"],"correct":3,"exp":"Limited attention spread across many channels usually means none is executed well enough to succeed."},{"q":"Customers discover the service online but cannot complete an order there. What should be reviewed?","opts":["Only the site's header photograph","The path from awareness to purchase and delivery","Only the number of promotional posts","Only the business name"],"correct":1,"exp":"Channels should support the complete intended customer journey."}]},
    {"key":"M5:Revenue Streams","rows":[{"q":"What do revenue streams describe?","opts":["The mechanisms by which the business earns money from customers","The cost of running the business","The list of competitors","The legal name of the business"],"correct":0,"exp":"They define exactly how money flows in, distinct from what is offered."},{"q":"Why is recurring revenue generally more valuable than an equivalent one-time sale?","opts":["It is always a larger total amount","It is predictable","It requires no customer relationship","It is easier to collect"],"correct":1,"exp":"Predictability of future income is valuable in itself, separate from the total amount earned."},{"q":"What does usage-based pricing align?","opts":["Marketing spend with sales","Product design with manufacturing","Cost with value for the customer","Staff salaries with revenue"],"correct":2,"exp":"Charging in proportion to use matches what a customer pays to what they actually get."},{"q":"A model mixes customer subscriptions and one-time setup fees without distinguishing them. What should improve?","opts":["Separate revenue sources, timing and assumptions","Only the invoice's logo","Only the spreadsheet colours","Only the account name"],"correct":0,"exp":"Revenue streams can have different economics and collection timing."}]},
    {"key":"M5:Cost Structure","rows":[{"q":"What is a fixed cost?","opts":["A cost that only applies to large businesses","A cost paid only once","A cost that always decreases over time","A cost that does not change with volume"],"correct":3,"exp":"Fixed costs such as rent or salaries stay constant regardless of how much is sold."},{"q":"What is the risk of a high fixed, low variable cost structure?","opts":["It requires volume to break even, but rewards strongly once achieved","It cannot be used by small businesses","It has no risk at all","It always costs more per unit"],"correct":0,"exp":"Below the volume needed to cover fixed costs, the business loses money; above it, profit grows quickly."},{"q":"What should be known before setting a price?","opts":["The competitor's marketing budget","The true cost per unit","The founder's personal savings","The size of the total market"],"correct":1,"exp":"Pricing without knowing true cost per unit risks selling at a loss without realising it."},{"q":"A cost forecast omits delivery fees that rise with each order. What must be included?","opts":["Relevant variable fulfilment costs","Only a higher revenue estimate","Only more fixed rent","Only the business registration number"],"correct":0,"exp":"The model must account for costs that change with activity."}]},
    {"key":"M5:Key Resources","rows":[{"q":"What are key resources?","opts":["The competitors in a market","The channels used to reach customers","The assets a business needs to deliver its value proposition","The customers a business serves"],"correct":2,"exp":"They are the physical, intellectual, human or financial assets required to operate."},{"q":"What question should be asked of each listed resource?","opts":["Does a competitor have it?","Can it be patented?","How expensive is it?","Is it truly necessary for this value proposition, or acquired out of ambition?"],"correct":3,"exp":"Necessity, not ambition or appearance, should determine what resources are pursued."},{"q":"Why avoid buying expensive resources before the model is proven?","opts":["It ties up capital an unproven business does not yet need to risk","Expensive resources are always inferior","Resources cannot be resold","It is illegal to own assets early"],"correct":0,"exp":"Committing capital to assets before validating the model increases risk without corresponding evidence of return."},{"q":"A service depends on specialist skills no team member possesses. What should the model identify?","opts":["Only a larger marketing budget","Only a different slogan","Only a longer proposal","How the required capability will be obtained"],"correct":3,"exp":"Key resources must be available for the model to operate."}]},
    {"key":"M5:Key Activities","rows":[{"q":"What are key activities?","opts":["Everything a business does","The few things the business cannot afford to do poorly","Only marketing tasks","Tasks performed by the founder personally"],"correct":1,"exp":"They are the small set of activities that most determine whether the model succeeds."},{"q":"What is a warning sign regarding key activities?","opts":["Reviewing them monthly","Spending time on them daily","Neglecting them in favour of easier, less important tasks","Assigning them to the most experienced staff"],"correct":2,"exp":"If effort drifts toward comfortable but less decisive tasks, the activities that matter most are being under-resourced."},{"q":"Can key activities change over time?","opts":["Only if the founder changes","Only for large companies","No, they are fixed at founding","Yes, as the business model shifts"],"correct":3,"exp":"What matters most to the model's success can shift as the model itself evolves."},{"q":"A founder's activity list is busy but ignores fulfilling paid orders. What should be prioritised?","opts":["The work essential to delivering the promised value","Only more social posts","Only redesigning stationery","Only attending unrelated events"],"correct":0,"exp":"Key activities should enable the business's core value delivery."}]},
    {"key":"M5:Key Partners","rows":[{"q":"What makes a partnership durable?","opts":["It benefits both sides clearly enough to survive disagreement","It is between friends","It involves no written terms","It is with the largest possible partner"],"correct":0,"exp":"Mutual, articulable benefit is what keeps a partnership functioning under strain."},{"q":"Why put partnership terms in writing even with trusted people?","opts":["It is required for taxation","Memory of an informal deal fades and diverges over time","It prevents any disagreement from ever occurring","Verbal agreements are illegal"],"correct":1,"exp":"Written terms prevent the drift in recollection that causes disputes later."},{"q":"What should be assessed about any key partner?","opts":["Their marketing budget","Their personal friendliness","What happens if they fail or withdraw","Their office location"],"correct":2,"exp":"Understanding the consequence of losing a partner reveals how much risk that dependency carries."},{"q":"A model depends on one supplier without checking reliability or terms. What should be assessed?","opts":["The dependency, responsibilities and alternatives","Only the supplier's logo","Only its social follower count","Only the colour of its catalogue"],"correct":0,"exp":"Partner relationships need practical dependency and performance review."}]},
    {"key":"M5:Business Model Review","rows":[{"q":"What is the purpose of this review?","opts":["Writing a new value proposition","Calculating taxes owed","Choosing a business name","Checking that the nine blocks are internally consistent with each other"],"correct":3,"exp":"Consistency across blocks is what turns nine separate answers into one coherent model."},{"q":"Where do founders most often discover a problem during this review?","opts":["Where one block quietly contradicts another","In the length of the document","In the font used","In the title of the canvas"],"correct":0,"exp":"Blocks built independently often do not actually support each other, and the contradiction is the real risk."},{"q":"How often should this kind of review happen?","opts":["Only once, before Module 6","As an ongoing habit as the model evolves","Only after the business fails","Only if investors request it"],"correct":1,"exp":"The model continues to change as the business learns, so consistency needs checking repeatedly, not once."},{"q":"Customer evidence contradicts the model's original channel assumption. What should a review do?","opts":["Update the model and test the revised approach","Preserve every assumption for consistency","Delete the evidence","Only change the canvas's title"],"correct":0,"exp":"Model review should incorporate what the venture has learned."}]},
    {"key":"M6:Product Design","rows":[{"q":"What should product design decisions be traced back to?","opts":["What competitors have built","The founder's personal interests","A specific customer need identified during validation","What is technically possible to build"],"correct":2,"exp":"Grounding decisions in validated need is what keeps design relevant to what customers actually want."},{"q":"What is a recurring design failure?","opts":["Testing with real customers","Keeping the product simple","Building too few features","Adding features because they are possible, not because customers asked for them"],"correct":3,"exp":"Capability-driven design adds complexity and cost without corresponding customer value."},{"q":"What should design account for regarding the customer's context?","opts":["Their actual device, connectivity, and time pressure","Only the founder's own device","The competitor's design choices","Only their stated preferences"],"correct":0,"exp":"Real usage conditions determine whether a design actually works for the customer."},{"q":"A product design satisfies the founder but users cannot complete the intended task. What should be revised?","opts":["The design against actual user needs and testing","Only the product's name","Only the founder's presentation","Only the packaging's gloss"],"correct":0,"exp":"Product design must support the intended user outcome."}]},
    {"key":"M6:Service Design","rows":[{"q":"What does service design cover?","opts":["Only the core moment of service delivery","Every touchpoint from discovery through after-service support","Only the pricing of the service","Only marketing materials"],"correct":1,"exp":"The full journey, not just the central delivery moment, shapes the customer's overall experience."},{"q":"Why can a technically excellent service still feel poor?","opts":["Because it was not advertised enough","Because customers are never satisfied","Because surrounding touchpoints like booking or support may be neglected","Because excellent service always costs more"],"correct":2,"exp":"Friction at booking, waiting or follow-up can undermine an otherwise strong core service."},{"q":"What should be tested to catch design gaps?","opts":["Only the price list","Only the marketing copy","Only the founder's opinion of the service","The full journey, experienced as a customer would"],"correct":3,"exp":"Walking through the entire experience reveals friction that reviewing the core service alone would miss."},{"q":"A service works at purchase but fails during handover. What should be mapped?","opts":["The full customer journey and operational touchpoints","Only the advertisement's layout","Only the company logo","Only the final invoice"],"correct":0,"exp":"Service quality depends on the complete delivery experience."}]},
    {"key":"M6:Minimum Viable Product (MVP)","rows":[{"q":"What is an MVP built to do?","opts":["Test a specific assumption with real customers as cheaply as possible","Serve as a lesser version of the final planned product","Impress investors with features","Replace the need for customer interviews"],"correct":0,"exp":"Its purpose is testing, not delivering a scaled-down final experience."},{"q":"What should be decided before building an MVP?","opts":["The final product's full feature list","The riskiest assumption to test and what result would validate it","The company's long-term hiring plan","The office location"],"correct":1,"exp":"A clear question and a defined test result are what make an MVP purposeful rather than arbitrary."},{"q":"Can an MVP operate manually behind the scenes?","opts":["Only if investors approve","No, it must always be fully automated","Yes, as long as it tests the assumption","Only for software products"],"correct":2,"exp":"What matters is testing the assumption, not whether the mechanism behind it is automated."},{"q":"An MVP includes many expensive features that do not test the main uncertainty. What should change?","opts":["Add all planned features first","Treat unfinished quality as acceptable everywhere","Avoid customer interaction","Reduce scope to the smallest useful test of that assumption"],"correct":3,"exp":"An MVP is designed for focused learning about a meaningful assumption."}]},
    {"key":"M6:Product Testing","rows":[{"q":"What are the two things product testing checks?","opts":["Marketing and branding","Legal compliance and taxes","Price and packaging","Functionality and usability"],"correct":3,"exp":"Whether the product works correctly, and whether real people can use it without confusion, are distinct checks."},{"q":"Why is testing with colleagues who understand the product a poor substitute for real customers?","opts":["They already understand the product and will not experience the confusion a new user does","Colleagues cannot be trusted with early products","It is more expensive than testing with customers","Colleagues are always dishonest"],"correct":0,"exp":"Familiarity with the product hides the exact confusion a first-time user would encounter."},{"q":"What should testers be observed doing, beyond being asked their opinion?","opts":["Their social media activity","Their actual behaviour while using the product","Their spending habits","Their opinion of competitors"],"correct":1,"exp":"Watching real usage reveals problems that a polite verbal opinion often does not."},{"q":"A prototype is tested only by the people who built it. What additional testing is useful?","opts":["Representative intended users completing relevant tasks","Only a faster computer","Only a new company slogan","Only a screenshot review by the founder"],"correct":0,"exp":"User testing can expose difficulties creators overlook."}]},
    {"key":"M6:Gathering Customer Feedback","rows":[{"q":"Why is 'it's good' not useful feedback?","opts":["It takes too long to collect","It is too positive","It gives no specific direction for what to change","Customers never say this"],"correct":2,"exp":"Vague impressions cannot be translated into a concrete product change."},{"q":"What makes feedback more actionable?","opts":["Asking for a general satisfaction score only","Collecting it long after the experience","Only asking loyal customers","Anchoring it to a specific recent moment of use"],"correct":3,"exp":"Specific, moment-based detail translates directly into identifiable changes."},{"q":"What should be done before acting on one complaint?","opts":["Look for the same pattern across several customers","Ignore all future feedback","Raise the price","Change the product immediately"],"correct":0,"exp":"A single voice may not represent the wider customer base; patterns across several are stronger evidence."},{"q":"Feedback contains contradictory requests from different users. What should be analysed?","opts":["The needs, segments and evidence behind the requests","Implement every request simultaneously","Choose only the loudest comment","Ignore all negative responses"],"correct":0,"exp":"Feedback needs interpretation in the business and user context."}]},
    {"key":"M6:Product Improvements","rows":[{"q":"What should prioritisation of product improvements weigh?","opts":["Only how recently the feedback arrived","How many are affected, how serious the issue is, and cost to fix","Only which customer complained loudest","Only how easy the fix is"],"correct":1,"exp":"Balancing impact, severity and cost is what allocates limited development time sensibly."},{"q":"What should be fixed before adding new features?","opts":["Only cosmetic issues","Only issues raised by investors","Problems that block customers from getting value","Nothing; new features always come first"],"correct":2,"exp":"Blocking issues undermine the core value already promised, and should be resolved before expanding scope."},{"q":"What is scope creep in this context?","opts":["Testing too many users","Fixing bugs too quickly","Launching too early","Minor requests quietly expanding into a much larger rebuild"],"correct":3,"exp":"Small requests can accumulate into major, unplanned work if not managed deliberately."},{"q":"A proposed improvement adds complexity without solving a measured problem. What should be evaluated?","opts":["Only its novelty","Its expected customer value and evidence of need","Only its implementation hours","Only its presentation animation"],"correct":1,"exp":"Improvements should justify their contribution to useful outcomes."}]},
    {"key":"M6:Quality Control","rows":[{"q":"What does quality control ensure?","opts":["That what customers receive matches what was promised, consistently","That prices stay the same","That marketing is accurate","That competitors cannot copy the product"],"correct":0,"exp":"Consistency between promise and delivery, across every unit, is the purpose of quality control."},{"q":"Why check quality as early as possible in the process?","opts":["It is required by law","Catching a defect early is cheaper than resolving a complaint afterward","Early checks are always easier to perform","It reduces the number of staff needed"],"correct":1,"exp":"Cost and reputational damage both rise the later a defect is caught."},{"q":"Why might an informal personal check stop working as a business grows?","opts":["Larger businesses do not need quality control","Growth makes quality automatically improve","One founder can no longer personally inspect every unit at higher volume","Customers stop caring about quality"],"correct":2,"exp":"Volume and multiple staff outpace what one person's informal oversight can cover."},{"q":"Defects reach customers because checks happen only after delivery. What should improve?","opts":["Only a stronger sales claim","Defined quality standards and checks during the process","Only a new logo","Only a longer product description"],"correct":1,"exp":"Quality control should detect issues before they affect customers."}]},
    {"key":"M6:Product Launch Planning","rows":[{"q":"What is a common launch planning failure?","opts":["Preparing operations before marketing","Launching to a small group first","Testing the product before launch","Treating launch only as a marketing event"],"correct":3,"exp":"Focusing on marketing alone while neglecting operational readiness risks demand the business cannot fulfil."},{"q":"What should be confirmed before driving traffic to a launch?","opts":["That operational capacity matches expected demand","That competitors have been informed","That the office is fully staffed","That the marketing budget is fully spent"],"correct":0,"exp":"Generating demand the operation cannot fulfil damages the business more than a quieter, well-served launch."},{"q":"Why might a soft launch to a smaller group be preferable?","opts":["It generates no revenue","It catches issues at a manageable scale before wider exposure","It avoids the need for a marketing message","It is required by regulation"],"correct":1,"exp":"Testing at smaller scale limits the damage of any problems the full launch would otherwise expose broadly."},{"q":"The product is ready but support and delivery are unprepared. What must the launch plan address?","opts":["Only the announcement image","Only the founder's speech","Only the product's nickname","Operational readiness across the customer journey"],"correct":3,"exp":"Launching requires more than completing the product itself."}]},
    {"key":"M7:Branding Fundamentals","rows":[{"q":"What is a brand, most fundamentally?","opts":["A legal registration","A logo and colour scheme","The associations and expectations customers hold about a business","A slogan"],"correct":2,"exp":"Visual elements express the brand, but the brand itself is the accumulated customer perception."},{"q":"What builds a brand faster than any single impressive moment?","opts":["A large advertising budget","A famous founder","An expensive logo","Consistency across every interaction"],"correct":3,"exp":"Repeated, reliable experience shapes expectations more than any isolated impressive event."},{"q":"What happens when a brand promise is broken repeatedly?","opts":["It becomes a liability rather than an asset","It strengthens customer loyalty","It is automatically forgiven","It has no effect on the brand"],"correct":0,"exp":"Repeated failure to deliver on what customers expect erodes rather than builds the brand."},{"q":"Customers receive different promises from a venture's website and sales team. What should be aligned?","opts":["Only the website's background colour","The brand's positioning, message and actual experience","Only the sales team's uniform","Only the file naming convention"],"correct":1,"exp":"Branding includes a coherent promise supported by delivery."}]},
    {"key":"M7:Choosing a Business Name","rows":[{"q":"What matters more than creativity when choosing a business name?","opts":["Whether it rhymes","Ease of saying, spelling and remembering","How impressive it sounds to the founder","Its length"],"correct":1,"exp":"Practical usability determines whether customers can actually find and refer the business."},{"q":"What should be checked before committing to a name?","opts":["The competitor's revenue","The weather forecast","Domain, social handle and trademark availability","The founder's horoscope"],"correct":2,"exp":"Conflicts discovered after building recognition around a name are far costlier to resolve."},{"q":"Why avoid a name that only makes sense in one language, if expansion is possible?","opts":["Multilingual names are always better","It affects the price of the domain","It is illegal","It could confuse or fail to translate in a future market"],"correct":3,"exp":"A name tied to one language's meaning may not carry over cleanly if the business grows beyond it."},{"q":"A proposed business name resembles an existing competitor. What should precede adoption?","opts":["Relevant name and brand-conflict checks under current local rules","Only buying the cheapest domain","Only designing a logo","Assuming an available username proves legal clearance"],"correct":0,"exp":"A usable name needs more than an available online handle."}]},
    {"key":"M7:Logo Design","rows":[{"q":"What is a logo's main job?","opts":["Recognition and legibility across contexts","Explaining the full business model","Winning design awards","Replacing the need for a business name"],"correct":0,"exp":"Quick, reliable recognition at a glance is what a logo needs to achieve, wherever it appears."},{"q":"Why test a logo at the smallest size it will appear?","opts":["Because size does not affect legibility","Because that is the most common way people will see it","Because larger logos are illegal","Because small logos are cheaper to print"],"correct":1,"exp":"A phone icon or small social media image is often the most frequent real-world context for a logo."},{"q":"Why should a logo work in a single colour?","opts":["Single colour is required by law","Colour reduces recognition","Colour printing or display is not always available","Colour logos are more expensive"],"correct":2,"exp":"Reliable legibility should not depend on conditions, like full-colour printing, that are not always present."},{"q":"A startup logo becomes unreadable on small packaging. What should be tested and revised?","opts":["Only the original large mock-up","Only the export date","Small-size clarity and practical reproduction","Only the founder's biography"],"correct":2,"exp":"A logo must work in its intended real applications."}]},
    {"key":"M7:Brand Identity","rows":[{"q":"What is brand identity?","opts":["Only the logo","The founder's personal style","The business's legal name","The consistent system of visual and verbal choices used everywhere"],"correct":3,"exp":"It is the full, consistent system applied across every touchpoint, not any single element."},{"q":"What does inconsistent tone across channels do to a brand?","opts":["Dilutes recognition by making touchpoints feel unconnected","Has no effect","Increases customer trust","Strengthens recognition"],"correct":0,"exp":"Customers struggle to connect inconsistent experiences as belonging to the same business."},{"q":"What matters most for a small business's brand identity?","opts":["Sophistication","Consistency","Cost of design","Number of colours used"],"correct":1,"exp":"Consistent application across every touchpoint builds recognition more reliably than sophisticated but inconsistent design."},{"q":"Different suppliers invent new colours and fonts for every asset. What would support consistency?","opts":["Only a different company name","A usable identity system with approved assets and guidance","Only more unrelated templates","Only longer invoices"],"correct":1,"exp":"Identity rules help others reproduce a recognisable visual system."}]},
    {"key":"M7:Marketing Fundamentals","rows":[{"q":"What are the four Ps of marketing?","opts":["Plan, Pitch, Pay, Publish","Product, Package, Post, Print","Product, Price, Place, Promotion","Profit, People, Process, Performance"],"correct":2,"exp":"The four Ps &mdash; Product, Price, Place, Promotion &mdash; are the classic framework for organising marketing decisions."},{"q":"Is marketing the same as advertising?","opts":["No, marketing only means social media","Yes, but only for large businesses","Yes, they are identical","No, advertising is only one promotional tool within marketing"],"correct":3,"exp":"Marketing is the whole system connecting product to customer; advertising is just one tool for the Promotion element."},{"q":"Where should marketing decisions start from?","opts":["A real customer need","Whatever the competitor is doing","The founder's personal taste","The cheapest available option"],"correct":0,"exp":"Marketing that starts from an actual customer need is far more likely to succeed than marketing built around the product alone."},{"q":"A founder runs promotions before defining an audience or offer. What should be clarified?","opts":["Only the promotion's animation","The customer, value proposition and marketing objective","Only the founder's social account","Only the size of the logo"],"correct":1,"exp":"Marketing needs a defined purpose and relevant audience."}]},
    {"key":"M7:Digital Marketing","rows":[{"q":"What is a key advantage of digital marketing over traditional advertising?","opts":["It is always free","Results are highly measurable and can be adjusted quickly","It requires no planning","It reaches only large businesses"],"correct":1,"exp":"Digital channels let a business see clear results and adjust campaigns quickly, unlike most traditional advertising."},{"q":"What should guide the choice of which digital channel to use?","opts":["Whichever channel is most expensive","Whichever channel is most popular globally","Where the target customer actually spends time","The founder's personal preference only"],"correct":2,"exp":"Effective channel choice follows the target customer's actual habits, not general popularity or personal preference."},{"q":"Can digital and traditional marketing be combined?","opts":["No, traditional marketing is now illegal","Yes, but only for large corporations","No, a business must choose only one","Yes, they can complement each other"],"correct":3,"exp":"Many businesses successfully combine digital and traditional marketing rather than treating them as mutually exclusive."},{"q":"A digital campaign produces clicks but almost no qualified enquiries. What should be investigated?","opts":["Audience fit, the offer and the conversion journey","Only the total impressions","Only the page's decorative icons","Only the company's email signature"],"correct":0,"exp":"Channel activity should be evaluated against meaningful outcomes."}]},
    {"key":"M7:Social Media Marketing","rows":[{"q":"What matters more for social media marketing over time?","opts":["Consistency and genuine engagement","Only posting adverts","Posting as rarely as possible","Posting on every possible platform at once"],"correct":0,"exp":"Consistent, on-brand posting combined with real engagement builds more trust than sporadic posting or one-way broadcasting."},{"q":"Why does replying to comments and messages matter?","opts":["It is legally required","It turns a broadcast channel into a two-way relationship that builds trust","It increases the cost of the platform","It has no real effect on customers"],"correct":1,"exp":"Two-way engagement builds loyalty and trust in a way one-way broadcasting cannot."},{"q":"How should a business choose which social platform to focus on?","opts":["Choose the platform with the fewest other businesses on it","Use every platform equally regardless of audience","Focus where the target audience is actually active","Choose randomly"],"correct":2,"exp":"Effort is best spent where the actual target audience already spends its time, rather than spread thin across every platform."},{"q":"A startup publishes frequently without knowing whom the posts should reach. What is missing?","opts":["Only more posting hours","Only additional unrelated hashtags","Only a new profile picture","An audience-led content objective and measurement plan"],"correct":3,"exp":"Social content should serve a defined customer and business purpose."}]},
    {"key":"M7:Email Marketing","rows":[{"q":"Why is an owned email list valuable compared to a social media following?","opts":["Email lists are required by law","Social media followers cannot receive offers","Email is always free while social media costs money","The business owns and controls the list directly, unlike a platform-dependent following"],"correct":3,"exp":"An email list is a direct, owned asset that survives changes to any third-party platform's rules or reach."},{"q":"What keeps an email list engaged over time?","opts":["Offering real, relevant value rather than constant hard selling","Never sending anything","Buying email addresses from other businesses","Sending as many promotional emails as possible"],"correct":0,"exp":"Genuine value keeps open rates high; constant selling without value drives people to ignore or unsubscribe."},{"q":"How should an email list be built?","opts":["By purchasing lists of strangers' addresses","Only from people who have genuinely opted in","By adding every contact in the founder's phone","It does not matter how the list is built"],"correct":1,"exp":"A list built from genuine consent keeps engagement healthy and avoids being marked as spam."},{"q":"A founder considers emailing an acquired list with unclear consent. What should be checked?","opts":["Only the list's number of addresses","Only the email's header image","Only the sender's preferred font","Permission, applicable rules and the ability to opt out"],"correct":3,"exp":"Email outreach needs an appropriate permission and compliance basis."}]},
    {"key":"M7:Content Marketing","rows":[{"q":"What is the core idea of content marketing?","opts":["Copying competitors' promotional material","Advertising a product directly in every message","Creating genuinely useful material that attracts and builds trust without a direct sales pitch every time","Publishing content as rarely as possible"],"correct":2,"exp":"Content marketing earns attention and trust through usefulness, rather than direct promotion in every piece."},{"q":"What should good content be based on?","opts":["Only the founder's personal interests","Content unrelated to the business","Whatever is easiest to produce","Real questions the target audience already has"],"correct":3,"exp":"Content that answers real audience questions is far more valuable and engaging than content chosen for convenience alone."},{"q":"Does content marketing typically work overnight?","opts":["No, it builds trust and effect over time through consistency","It never produces any measurable benefit","Only if paid advertising is added","Yes, results are always immediate"],"correct":0,"exp":"Content marketing's trust-building effect compounds with consistent effort over time, rather than producing instant results."},{"q":"A venture's articles attract readers with needs unrelated to its service. What should change?","opts":["Only the word count","Only the thumbnail border","Only the publishing date format","The content's relevance to the intended audience and offer"],"correct":3,"exp":"Useful content should connect the audience's needs with the venture's purpose."}]},
    {"key":"M7:Search Engine Optimization (SEO)","rows":[{"q":"What is the goal of SEO?","opts":["To pay for every click a website receives","To help a website or listing be found naturally in search results for relevant terms","To hide a business from search engines","To make a website slower but more detailed"],"correct":1,"exp":"SEO aims to help relevant searchers find a business naturally, without paying for each individual click."},{"q":"Why does consistent business information across listings matter for SEO?","opts":["Consistency actually lowers ranking","It has no effect on search ranking","Search engines rank consistent, verifiable information more highly","It is only relevant for very large companies"],"correct":2,"exp":"Accurate, matching details across listings help search engines trust and rank a business's information."},{"q":"Is SEO typically a one-time task?","opts":["SEO does not require any content changes","SEO only applies to paid advertising","Yes, it is done once and never revisited","No, it is a gradual, ongoing practice"],"correct":3,"exp":"SEO works best as a continuous practice, since search behaviour, competitors and content all change over time."},{"q":"A startup fills a page with repeated keywords but omits useful answers. What should improve?","opts":["Clear useful content that meets relevant search intent","Add more identical keywords everywhere","Hide the main information","Assume repetition guarantees first position"],"correct":0,"exp":"Search visibility work should support useful accessible information."}]},
    {"key":"M7:Advertising","rows":[{"q":"How does advertising differ from organic content marketing?","opts":["Advertising is paid and delivers immediate, guaranteed reach that stops when spending stops","There is no real difference","Organic content always reaches more people than advertising","Advertising is always cheaper"],"correct":0,"exp":"Advertising guarantees reach in exchange for payment, but that reach ends as soon as spending stops, unlike accumulating organic content."},{"q":"What makes an advert effective?","opts":["Including as many messages as possible","A clear, single message with one clear next step","Avoiding any call to action","Targeting the widest possible audience regardless of relevance"],"correct":1,"exp":"A focused, single message with a clear next step is remembered and acted on far more than a crowded advert."},{"q":"Should advertising replace organic marketing entirely?","opts":["Organic marketing always costs more than advertising","Yes, organic marketing is never useful","No, the two typically complement each other","Advertising is illegal without organic marketing"],"correct":2,"exp":"Advertising and organic marketing work best together, each covering what the other cannot provide alone."},{"q":"An advertisement receives many views but its claim is unsupported. What must be corrected?","opts":["Only the banner's colour","Only the campaign filename","Only the number of placements","The accuracy and evidence behind the advertised promise"],"correct":3,"exp":"Advertising should communicate accurate substantiated information."}]},
    {"key":"M7:Customer Acquisition","rows":[{"q":"What is customer acquisition cost?","opts":["The price charged to every customer","The cost of running the whole business for a year","The total revenue of a business","The average cost of winning one new customer"],"correct":3,"exp":"Customer acquisition cost measures how much, on average, a business spends to gain each new customer."},{"q":"Why compare acquisition cost to customer lifetime value?","opts":["To judge whether an acquisition channel is actually sustainable","Lifetime value has no relation to acquisition cost","To increase prices arbitrarily","Because it is a legal requirement"],"correct":0,"exp":"A channel that costs more to acquire a customer than that customer is ever worth is not sustainable, however good it looks short-term."},{"q":"What is often one of the lowest-cost acquisition channels?","opts":["Expensive nationwide advertising campaigns","Referrals from satisfied existing customers","Buying large, unverified contact lists","Random, untargeted promotion"],"correct":1,"exp":"Referrals from happy existing customers typically cost far less than paid channels while bringing loyal new buyers."},{"q":"A startup spends $240 to acquire 12 paying customers. What is the average acquisition cost in this example?","opts":["$12 per customer","$240 per customer","$20 per customer","$2 per customer"],"correct":2,"exp":"Dividing acquisition spending by acquired customers gives the stated average."}]},
    {"key":"M8:Sales Fundamentals","rows":[{"q":"What is the goal of good selling?","opts":["Avoiding ever asking for the sale","Pressuring anyone into buying regardless of fit","Helping a real prospect decide clearly whether an offer solves their problem","Reciting a fixed script without listening"],"correct":2,"exp":"Good selling helps a genuinely interested prospect reach a clear, honest decision, rather than applying pressure."},{"q":"What are the typical stages a sale moves through?","opts":["Price, product, place, promotion","Hiring, training, firing","Discount, refund, return","Attention, interest, desire, action"],"correct":3,"exp":"Attention, interest, desire and action describe the typical stages a prospect moves through toward a purchase."},{"q":"Why does asking for the sale directly matter?","opts":["Hoping the customer offers to buy rarely works as well as asking directly at the right moment","It is rude and should be avoided","It only matters for expensive products","It is unnecessary if the product is good enough"],"correct":0,"exp":"A clear, well-timed request to buy is usually necessary to convert genuine interest into a completed sale."},{"q":"A salesperson describes features without understanding the prospect's needs. What should happen first?","opts":["Make more confident promises","Clarify the customer's problem and fit with the offer","Increase the number of technical terms","Discuss only the salesperson's targets"],"correct":1,"exp":"Good sales starts with understanding whether the offer is useful."}]},
    {"key":"M8:Sales Funnel","rows":[{"q":"Why is it called a sales funnel?","opts":["Because it only applies to liquid products","Because naturally fewer people remain at each later stage, like liquid narrowing through a funnel","Because it was invented by a plumber","Because sales always increase at each stage"],"correct":1,"exp":"The funnel shape reflects that more people enter at awareness than complete a purchase, narrowing at each stage."},{"q":"What does mapping a sales funnel help a founder do?","opts":["Avoid tracking any numbers","Replace the need for a good product","Identify exactly where prospects are being lost","Guarantee every visitor becomes a customer"],"correct":2,"exp":"A funnel view pinpoints the specific stage causing the most drop-off, guiding where to focus effort."},{"q":"If many people visit but few buy, where is the likely problem?","opts":["There is no way to know","Advertising spend is too high","Awareness","The decision stage &mdash; price, trust, or selection"],"correct":3,"exp":"Strong traffic with weak conversion points to a problem at the decision stage, not at the awareness stage."},{"q":"Many prospects request a demo but few progress to purchase. What should be examined?","opts":["Only the total visitor count","Only the logo's placement","Only the number of sales slides","The reasons for drop-off at that stage"],"correct":3,"exp":"Funnel analysis identifies where and why prospects stop progressing."}]},
    {"key":"M8:Pricing Strategies","rows":[{"q":"What is cost-plus pricing?","opts":["Setting price as cost plus a fixed markup","Setting price with no reference to cost at all","Pricing based on customer income","Pricing based only on what competitors charge"],"correct":0,"exp":"Cost-plus pricing adds a fixed markup on top of the business's own costs to set the price."},{"q":"When does value-based pricing work best?","opts":["For common products that are easy to compare directly","For unique, hard-to-compare products where perceived value can exceed simple cost","Only for imported goods","Only when costs are unknown"],"correct":1,"exp":"A distinctive, hard-to-compare offer supports pricing based on the value the customer perceives, not just cost."},{"q":"Should a pricing strategy stay fixed forever once chosen?","opts":["Pricing strategy has no relation to competition","Yes, changing price ever is bad practice","No, it should be revisited as costs, competition, and perception change","Prices can only ever increase, never decrease"],"correct":2,"exp":"Costs, competitive offers, and customer perception all change over time, so a pricing strategy should be reviewed periodically."},{"q":"A new price increases sales volume but reduces contribution per order sharply. What should be evaluated?","opts":["Only the number of orders","Its effect on total contribution, capacity and demand","Only the competitor's slogan","Only the price label's colour"],"correct":1,"exp":"Pricing decisions need both customer response and economic effects."}]},
    {"key":"M8:Negotiation Skills","rows":[{"q":"What is the goal of skilled negotiation?","opts":["Always paying the lowest possible price regardless of the relationship","Avoiding any compromise","Defeating the other side completely","Reaching an agreement both sides find genuinely acceptable"],"correct":3,"exp":"A durable agreement requires both sides to find the outcome acceptable, not just one side winning outright."},{"q":"Why does having a genuine alternative help in negotiation?","opts":["It removes desperation and strengthens your position","It has no real effect on the outcome","It obligates you to walk away regardless of terms","It weakens your position by distracting you"],"correct":0,"exp":"Knowing you have another option if the deal fails removes pressure to accept unfavourable terms out of desperation."},{"q":"What often happens to a deal that leaves one side feeling cheated?","opts":["It always becomes more profitable over time","It rarely survives beyond the first transaction","It has no effect on future dealings","It automatically renews every year"],"correct":1,"exp":"An unfair-feeling deal tends to damage trust and the relationship, undermining future business."},{"q":"A customer demands a lower price but might accept a narrower scope. What should be explored?","opts":["Promise every feature at any price","Ignore delivery costs","Threaten to hide defects","A trade-off that fits both parties' underlying needs"],"correct":3,"exp":"Negotiation can adjust terms beyond the headline price."}]},
    {"key":"M8:Customer Service","rows":[{"q":"What does customer service cover?","opts":["Only advertising","Only the moment of purchase","The entire experience before, during, and after a purchase","Only complaint handling"],"correct":2,"exp":"Good customer service spans the whole relationship, not just the transaction moment."},{"q":"What can a well-handled complaint achieve?","opts":["It has no effect on future loyalty","It should always be avoided by refusing complaints","It always damages the relationship permanently","It can build more loyalty than a purchase with no issues at all"],"correct":3,"exp":"Handling a complaint well can strengthen trust and loyalty more than a flawless but unremarkable transaction."},{"q":"Why is strong customer service often a durable advantage?","opts":["Because it is often harder for competitors to copy than the product itself","Because it costs more than advertising","Because customers never notice it","Because products can rarely be improved"],"correct":0,"exp":"While competitors can often copy a product, consistently strong service is harder to replicate, making it a durable advantage."},{"q":"A customer reports a delivery failure and receives conflicting responses. What should improve?","opts":["Clear ownership, accurate information and a resolution process","Only a friendlier logo","Only a larger refund-policy heading","Only more promotional messages"],"correct":0,"exp":"Service recovery needs coordinated practical action."}]},
    {"key":"M8:Customer Retention","rows":[{"q":"Why is customer retention often cheaper than acquisition?","opts":["Because retention is only relevant to large companies","Because retained customers already have an established relationship and trust","Because retention requires no effort at all","Because new customers always cost less"],"correct":1,"exp":"Existing trust and relationship with retained customers make them cheaper to keep than new customers are to win."},{"q":"What is customer churn?","opts":["A type of pricing strategy","The rate at which new customers are acquired","Customers leaving or stopping purchases over time","The total revenue of a business"],"correct":2,"exp":"Churn refers to existing customers leaving or ceasing to purchase, which can undermine growth even alongside new sign-ups."},{"q":"What is a warning sign a business should track for?","opts":["Stable pricing over multiple years","A loyalty programme with too many members","Consistent product quality","Growing new sales while quietly losing existing customers"],"correct":3,"exp":"Growing new sales while existing customers quietly leave can mask a retention problem that undermines overall growth."},{"q":"Customers buy once but leave because promised support is absent. What should retention work address?","opts":["Only more acquisition advertisements","Only a loyalty slogan","The actual post-purchase experience","Only the founder's biography"],"correct":2,"exp":"Retention depends on continuing value and reliable delivery."}]},
    {"key":"M8:CRM Basics","rows":[{"q":"What does CRM stand for?","opts":["Customer Relationship Management","Customer Retail Marketing","Central Revenue Model","Company Resource Management"],"correct":0,"exp":"CRM stands for Customer Relationship Management, the practice of systematically tracking customer information."},{"q":"Can a simple spreadsheet count as a basic form of CRM?","opts":["No, CRM always requires expensive software","Yes, a consistently used spreadsheet is a legitimate starting point","No, CRM only applies to online businesses","Yes, but only if it tracks financial data"],"correct":1,"exp":"A simple, consistently maintained spreadsheet is a valid, low-cost starting point for customer relationship tracking."},{"q":"Why does CRM value grow as a business gains more customers?","opts":["It does not grow; CRM matters equally at every size","Because software becomes cheaper with more customers","Because human memory alone cannot reliably track many individual relationships","Because CRM is required by law past a certain size"],"correct":2,"exp":"As customer numbers grow beyond what memory can reliably track, systematic records become increasingly valuable."},{"q":"Customer follow-ups are missed because records contain no next steps. What should be recorded?","opts":["Only the customer's favourite colour","Only more unrelated contacts","Only the sales team's logo","Relevant interaction history, ownership and follow-up actions"],"correct":3,"exp":"CRM records should support practical customer relationship work."}]},
    {"key":"M8:Closing Sales","rows":[{"q":"What is closing in a sales conversation?","opts":["Describing every possible product feature","Avoiding ever mentioning price","Ending the conversation without a decision","Directly and confidently asking the prospect to make the purchase decision"],"correct":3,"exp":"Closing means clearly asking the prospect to commit to the purchase, rather than leaving the decision unaddressed."},{"q":"What is a buying signal?","opts":["A specific question, like about delivery or payment, suggesting readiness to buy","A request for a lower price only","A complaint about the product","A sign the prospect has lost interest"],"correct":0,"exp":"Specific, practical questions about delivery, payment, or availability often signal genuine readiness to purchase."},{"q":"Why do promising sales conversations sometimes fail to convert?","opts":["The prospect was never interested at all","No one asked clearly and confidently for the sale at the right moment","The product was too well made","The price was too low"],"correct":1,"exp":"A common reason for lost sales is failing to ask directly for the decision once genuine interest and buying signals appear."},{"q":"A prospect is ready to buy but the scope and payment terms remain unclear. What should be confirmed?","opts":["Only a more forceful sales slogan","Only the proposal's border","Only the salesperson's signature image","The agreed offer, obligations and next steps"],"correct":3,"exp":"Closing should establish a clear shared transaction."}]},
    {"key":"M9:Financial Literacy","rows":[{"q":"What does financial literacy require?","opts":["Hiring an accountant and never reviewing numbers personally","A full accounting degree","Understanding a core set of concepts like revenue, cost, profit, and cash flow","Memorising every tax law"],"correct":2,"exp":"Basic financial literacy means understanding core concepts well enough to read simple reports, not formal accounting training."},{"q":"Why do some promising businesses fail despite a strong idea?","opts":["Financial literacy has no relation to business survival","Strong ideas always come with strong finances automatically","Ideas alone always guarantee success","The founder never fully understood the numbers until it was too late"],"correct":3,"exp":"A weak grasp of the numbers can undermine even a genuinely strong business idea."},{"q":"What is one benefit of financial literacy even when a founder hires an accountant?","opts":["It allows the founder to ask better, more informed questions","It eliminates the need for any bookkeeping","It guarantees the business will be profitable","It has no benefit once an accountant is hired"],"correct":0,"exp":"Understanding the numbers helps a founder engage meaningfully with an accountant, rather than trusting reports blindly."},{"q":"A founder treats a loan receipt as sales revenue. What should be distinguished?","opts":["Only cash denominations","Financing inflows from income earned through operations","Only bank statement colours","Only the lender's logo"],"correct":1,"exp":"Different financial flows have different accounting meanings."}]},
    {"key":"M9:Startup Costs","rows":[{"q":"What do startup costs include?","opts":["Only inventory purchased for resale","Everything a business must spend before it can begin operating and earning","Only the cost of registering the business","Only advertising expenses"],"correct":1,"exp":"Startup costs span equipment, inventory, registration, deposits and marketing needed before operations begin."},{"q":"Why should a startup budget include a buffer?","opts":["Because it guarantees extra profit","Buffers are unnecessary if a founder is careful","Because unexpected expenses are common and rarely fully forecast","Because buffers are legally required"],"correct":2,"exp":"Few founders forecast every expense perfectly, so a buffer protects against the inevitable unplanned cost."},{"q":"A startup omits equipment deposits and setup charges from its launch budget. What is the planning error?","opts":["Having too few customers from day one","Registering the business too early","Charging too much for products","Underestimating the funding needed to reach launch"],"correct":3,"exp":"A launch budget should account for the relevant setup costs and funding needs before operations can sustain themselves."},{"q":"A launch budget includes equipment but omits deposits and early operating cash. What should be reviewed?","opts":["Only the equipment's colour","Only the business name","The complete funding required before sustainable cash collection","Only a larger revenue target"],"correct":2,"exp":"Startup planning needs the relevant launch and early cash requirements."}]},
    {"key":"M9:Budgeting","rows":[{"q":"What is a budget?","opts":["A plan for how money will be spent and earned over a period of time","A legal document required to open a business","A fixed number that never changes","A record of only past expenses"],"correct":0,"exp":"A budget is a forward-looking plan for spending and earning, not simply a historical record."},{"q":"What provides a budget's most useful information?","opts":["The initial plan alone, without comparison","The gap between what was planned and what actually happened","The total amount of money spent","How attractively the budget document is formatted"],"correct":1,"exp":"Comparing plan against actual results reveals where assumptions were wrong, which is often the most valuable insight."},{"q":"Should a budget be treated as fixed once written?","opts":["A budget has no relationship to actual spending","Yes, changing a budget undermines its purpose","No, it should be revised as real conditions change","Budgets are only relevant for one week"],"correct":2,"exp":"Real conditions change, so a useful budget is revisited and adjusted rather than treated as permanently fixed."},{"q":"Actual spending repeatedly exceeds the budget in one category. What should happen?","opts":["Hide the actual transactions","Automatically delete the category","Assume the original estimate remains correct","Investigate the variance and revise actions or assumptions"],"correct":3,"exp":"Budget review should explain differences and support decisions."}]},
    {"key":"M9:Bookkeeping","rows":[{"q":"What is bookkeeping?","opts":["A marketing activity","A legal requirement only for large companies","A once-a-year summary of business performance","The ongoing recording of every financial transaction a business makes"],"correct":3,"exp":"Bookkeeping means consistently recording every transaction as it happens, not summarising after the fact."},{"q":"Why does consistent, ongoing recording beat reconstructing records later?","opts":["Because reconstructing from memory later is less accurate and reliable","Because it is required by law to record daily","There is no real difference in accuracy","Because software cannot process old transactions"],"correct":0,"exp":"Recording transactions as they happen is more accurate and reliable than trying to recall them from memory later."},{"q":"Why should personal and business finances be kept separate?","opts":["Only large companies need to separate them","To avoid confusion and errors in business records","Because it is impossible to spend personal money otherwise","Separation has no effect on bookkeeping accuracy"],"correct":1,"exp":"Mixing personal and business finances makes accurate business record-keeping much harder and more error-prone."},{"q":"A founder records a purchase with no date, amount or supporting evidence. What must improve?","opts":["Only the spreadsheet's colours","Only the company's slogan","Complete traceable transaction records","Only the folder's size"],"correct":2,"exp":"Reliable bookkeeping requires identifiable supported transactions."}]},
    {"key":"M9:Cash Flow","rows":[{"q":"How does cash flow differ from profit?","opts":["Cash flow only matters for large businesses","They are exactly the same thing","Cash flow tracks the actual timing of money in and out, while profit is an accounting figure that can look healthy even when cash is low","Profit always equals the cash a business has on hand"],"correct":2,"exp":"A business can show a profit on paper while actual cash is critically low, which is why cash flow is tracked separately."},{"q":"What can cause a timing gap between recorded profit and available cash?","opts":["Paying all suppliers in cash immediately","Having no customers at all","Reducing prices","Selling products on credit, with payment arriving later than the recorded sale"],"correct":3,"exp":"Credit sales record profit immediately, but the actual cash often arrives well after the sale is recorded."},{"q":"Why is forecasting cash flow useful?","opts":["It reveals gaps between money owed and money available before they become a crisis","It replaces the need for bookkeeping","It guarantees a business will always have enough cash","It has no practical use for a small business"],"correct":0,"exp":"Forecasting ahead lets a founder see and address a coming cash shortfall before it becomes an emergency."},{"q":"A profitable venture cannot pay tomorrow's supplier because customers pay next month. What is the issue?","opts":["Proof that profit and cash are identical","A guarantee of tax exemption","A branding inconsistency","A timing gap between cash receipts and payments"],"correct":3,"exp":"Cash availability depends on when money actually moves."}]},
    {"key":"M9:Profit & Loss","rows":[{"q":"What does a Profit & Loss statement summarise?","opts":["Only the business's total assets","Revenue, costs, and resulting profit or loss over a specific period","Only the business's debts","Only the founder's personal finances"],"correct":1,"exp":"A P&L reports revenue, costs, and the resulting profit or loss for a defined period."},{"q":"How is profit calculated on a P&L?","opts":["Total assets minus total debts","Total costs divided by revenue","Total revenue minus total costs","Total revenue plus total costs"],"correct":2,"exp":"Profit is the revenue remaining after subtracting all direct and operating costs."},{"q":"Why review a P&L monthly rather than only yearly?","opts":["Monthly review is required by law","It eliminates the need for bookkeeping","Monthly review has no advantage over yearly review","It catches negative trends, like shrinking margins, while they are still small and correctable"],"correct":3,"exp":"Frequent review surfaces problems early, while there is still time to correct course, rather than discovering them only at year-end."},{"q":"A founder includes a bank loan as operating revenue in the profit calculation. What should be corrected?","opts":["Only the statement's heading","Only the bank's logo","The classification of financing separately from revenue","Only the file's name"],"correct":2,"exp":"Borrowed funding is not income earned from selling goods or services."}]},
    {"key":"M9:Balance Sheet","rows":[{"q":"What does a balance sheet show?","opts":["A snapshot of assets, liabilities, and equity at one point in time","Only future sales projections","Only the business's marketing spend","Revenue and costs over a period"],"correct":0,"exp":"A balance sheet captures assets, liabilities, and equity as they stand at a single moment, unlike a P&L which covers a period."},{"q":"What is the balance sheet's defining rule?","opts":["Equity always equals total revenue","Assets always equal liabilities plus equity","Revenue always equals costs","Liabilities are always zero for a healthy business"],"correct":1,"exp":"Assets equal liabilities plus equity, reflecting that everything owned was funded by debt or by the owner's own stake."},{"q":"What can growing liabilities faster than assets indicate?","opts":["The business has no debts at all","The business is definitely thriving","The owner's actual equity stake may be shrinking, a possible warning sign","Nothing meaningful; only revenue matters"],"correct":2,"exp":"If liabilities grow faster than assets, the owner's equity can shrink even while the business appears larger."},{"q":"Assets total $8,000 and liabilities total $3,000 in a simple balance sheet. What is equity?","opts":["$11,000","$3,000","$24,000","$5,000"],"correct":3,"exp":"The accounting equation gives equity as assets minus liabilities."}]},
    {"key":"M9:Break-even Analysis","rows":[{"q":"What does the break-even point represent?","opts":["The maximum possible profit a business can earn","The point where a business has zero costs","The average price of a single product","The point where total revenue exactly equals total costs"],"correct":3,"exp":"Break-even is where revenue and total costs are exactly equal, with neither profit nor loss."},{"q":"How is break-even sales volume calculated?","opts":["Fixed costs divided by the contribution margin per unit","Variable costs divided by fixed costs","Total costs multiplied by price","Total revenue divided by total costs"],"correct":0,"exp":"Break-even volume equals fixed costs divided by the contribution margin (price minus variable cost) per unit."},{"q":"In a break-even model, what describes a fixed cost within the relevant activity range?","opts":["A cost that rises with every unit sold","A cost that stays constant within the model's relevant activity range","A cost that only occurs once a year","A cost that always equals zero"],"correct":1,"exp":"Fixed costs remain constant over the relevant activity range; capacity changes can alter the cost level."},{"q":"Fixed costs are $600 and contribution is $6 per unit, with both unchanged in the model. How many units break even?","opts":["3,600 units","600 units","6 units","100 units"],"correct":3,"exp":"Break-even units equal fixed costs divided by contribution per unit."}]},
    {"key":"M9:Pricing","rows":[{"q":"What three factors does pricing draw together?","opts":["Only what competitors charge","Only the cost of raw materials","Cost, perceived value, and competitive context","Only the founder's personal preference"],"correct":2,"exp":"A well-considered price balances cost, the value customers perceive, and the competitive market context."},{"q":"What risk comes from pricing purely on cost alone?","opts":["The business will always be highly profitable","There is no risk at all","Customers will always pay more than expected","The price may be uncompetitively low or fail to capture available value"],"correct":3,"exp":"Ignoring customer willingness to pay when pricing from cost alone can leave real value uncaptured."},{"q":"Should price stay fixed permanently once set?","opts":["No, it can be adjusted as costs, demand and competition change","Price has no relationship to competition","Price should only ever increase","Yes, changing price is always harmful"],"correct":0,"exp":"Since underlying conditions change, price is reasonably revisited rather than fixed forever."},{"q":"A product sells for $10 and has $7 variable cost per unit. What remains toward fixed costs and profit?","opts":["$10 net profit per unit","$3 contribution per unit","$7 contribution per unit","$17 contribution per unit"],"correct":1,"exp":"Contribution is selling price minus the variable cost in the stated model."}]},
    {"key":"M9:Financial Forecasting","rows":[{"q":"What is financial forecasting?","opts":["A legal requirement for every business","Projecting future revenue, costs, and cash position from stated assumptions","A guaranteed prediction of exact future results","A record of only past transactions"],"correct":1,"exp":"Forecasting is a structured, assumption-based projection of the future, not a guarantee."},{"q":"Why should forecast assumptions be made explicit?","opts":["It has no practical benefit","To make the forecast harder for others to understand","So a founder can identify exactly which prediction was wrong when reality differs","Explicit assumptions are legally required"],"correct":2,"exp":"Clear, explicit assumptions make it possible to pinpoint what to adjust when actual results diverge from the forecast."},{"q":"What is a key benefit of forecasting for a founder?","opts":["It guarantees the business will never run short of cash","It eliminates the need for bookkeeping","It removes the need for any future planning","It gives time to prepare for funding needs, hiring, or inventory before they become urgent"],"correct":3,"exp":"Forecasting surfaces future needs early enough for a founder to plan and act, rather than reacting under pressure."},{"q":"A forecast assumes rapid growth without explaining customer acquisition. What should be made explicit?","opts":["The drivers and evidence behind the sales assumptions","Only the spreadsheet's title","Only a larger final profit figure","Only the founder's optimism"],"correct":0,"exp":"A useful forecast links results to reviewable assumptions."}]},
    {"key":"M10:Bootstrapping","rows":[{"q":"What defines bootstrapping?","opts":["Growing a business using personal savings and reinvested revenue rather than outside investment","Borrowing exclusively from banks","Selling shares to venture capital investors","Relying entirely on government grants"],"correct":0,"exp":"Bootstrapping means funding growth internally, from savings and reinvested earnings, instead of outside investors."},{"q":"What is a key advantage of bootstrapping?","opts":["Guaranteed faster growth than any other funding method","Full ownership and decision-making control for the founder","No need to ever generate revenue","Automatic access to unlimited funds"],"correct":1,"exp":"Because no outside investor is involved, the founder keeps full ownership and control of decisions."},{"q":"What is a typical trade-off of bootstrapping?","opts":["Mandatory involvement of a bank","No trade-off exists","Slower growth, since spending is limited to what the business itself generates","Complete loss of control over the business"],"correct":2,"exp":"Because spending is constrained to internal resources, growth under bootstrapping is usually slower than with outside funding."},{"q":"A founder funds growth from operations and personal resources. What constraint should be monitored?","opts":["Only the number of investors","Only a larger public valuation","Available cash and the pace the venture can sustain","Only the office's appearance"],"correct":2,"exp":"Self-funded growth must fit the venture's practical cash capacity."}]},
    {"key":"M10:Friends & Family Funding","rows":[{"q":"What distinguishes friends and family funding from institutional funding?","opts":["It always requires a formal business plan","It is illegal in most countries","It always comes with the highest interest rates","It relies on personal trust rather than a formal track record"],"correct":3,"exp":"Friends and family invest based on personal relationships and trust, often before any formal track record exists."},{"q":"What is a distinct risk of friends and family funding?","opts":["A failed business can damage the personal relationship, not just cause financial loss","It is only available to large companies","It always requires giving up majority ownership","It has no risk at all"],"correct":0,"exp":"Because personal relationships are involved, business failure can cause relationship harm beyond the financial loss."},{"q":"Why should terms be put in writing, even informally?","opts":["Only banks require written terms","To prevent future disputes about whether the money was a loan, gift, or investment","Written terms are legally meaningless","To make the arrangement more complicated than necessary"],"correct":1,"exp":"Clear written terms help avoid misunderstandings later about the nature and expectations of the funding."},{"q":"A relative supplies money without agreement on whether it is a gift, loan or investment. What should be clarified?","opts":["The nature, risks and written terms of the arrangement","Only the payment's nickname","Only the family photograph","Only the venture's logo"],"correct":0,"exp":"Personal trust does not replace clear funding expectations."}]},
    {"key":"M10:Angel Investors","rows":[{"q":"Who are angel investors?","opts":["Crowdfunding platform operators","Government agencies providing grants","Individuals investing personal money into early-stage startups for equity","Banks offering business loans"],"correct":2,"exp":"Angel investors are individuals who put their own money into early startups in exchange for part ownership."},{"q":"What do angel investors often provide beyond money?","opts":["Free office space only","Guaranteed customers","Nothing beyond the capital itself","Mentorship, experience, and valuable industry contacts"],"correct":3,"exp":"Many angel investors, having built their own businesses, offer valuable guidance and connections alongside their capital."},{"q":"What does a founder typically give up when accepting angel investment?","opts":["Part ownership (equity) and some decision-making influence","Nothing at all","Full control of all future decisions","The right to ever seek further funding"],"correct":0,"exp":"Angel investment is exchanged for equity, meaning the founder shares part ownership and some influence over decisions."},{"q":"An angel offer provides funding in exchange for ownership and certain decisions. What must the founder understand?","opts":["Only the investor's social popularity","Dilution, rights and the actual investment terms","Only the pitch deck's design","Only the size of the initial transfer"],"correct":1,"exp":"Equity investment affects ownership and governance as well as cash."}]},
    {"key":"M10:Venture Capital","rows":[{"q":"What does venture capital typically seek?","opts":["Only government-registered businesses","Startups with potential for very rapid, large-scale growth","Any small business regardless of growth potential","Businesses with no risk at all"],"correct":1,"exp":"VC funds specifically pursue businesses capable of rapid, large-scale growth to generate large returns."},{"q":"Why do VC firms focus on high-growth potential businesses?","opts":["Because it is required by law","Because slower-growth businesses are illegal to fund","To offset the many startups that fail, seeking very high returns from the few that succeed","Because all startups grow at the same rate"],"correct":2,"exp":"Since many VC-backed startups fail, the fund needs very high returns from its successes to be viable overall."},{"q":"Is a steady, profitable business unsuited to VC funding a failure?","opts":["VC funding is required for any business to be legitimate","Steady businesses are always eligible for VC funding","Yes, any business not suited to VC is considered a failure","No, it simply reflects a mismatch with the VC model, not a flaw in the business"],"correct":3,"exp":"A stable, profitable business can be entirely successful while simply not fitting the specific growth profile VC funds seek."},{"q":"A venture has modest steady growth but seeks investors expecting a large scalable return. What should be assessed?","opts":["The fit between its model and investor expectations","Only the venture's domain name","Only the investor's logo","Only the founder's confidence"],"correct":0,"exp":"Funding suitability depends on the venture's economics and ambitions."}]},
    {"key":"M10:Crowdfunding","rows":[{"q":"What is crowdfunding?","opts":["Raising money from a large number of individuals, typically via an online platform","A single large investment from one bank","A government grant programme","A type of business loan from a single lender"],"correct":0,"exp":"Crowdfunding gathers smaller contributions from many people, usually through an online platform."},{"q":"What can contributors receive in exchange for a crowdfunding contribution?","opts":["Nothing at all, by definition","An early product, a reward, or in some models, equity","Guaranteed employment at the company","A government tax refund"],"correct":1,"exp":"Depending on the campaign model, contributors might receive an early product, a reward, or an equity stake."},{"q":"What extra value does a crowdfunding campaign provide beyond funds raised?","opts":["It eliminates the need for any further marketing","It has no value beyond the money raised","It validates real market demand before larger investment is committed","It guarantees future venture capital funding"],"correct":2,"exp":"A successful campaign demonstrates that real people are willing to pay in advance, a strong signal of genuine demand."},{"q":"A reward campaign accepts orders without costing fulfilment. What should be planned?","opts":["Production, delivery, fees and commitments to backers","Only the campaign photograph","Only a higher funding target","Only a longer founder biography"],"correct":0,"exp":"Funds raised come with practical fulfilment responsibilities."}]},
    {"key":"M10:Business Loans","rows":[{"q":"How does a business loan differ from equity funding?","opts":["A loan requires giving up part ownership, just like equity","A loan is only available to government agencies","There is no meaningful difference","A loan must be repaid with interest regardless of performance, without giving up ownership"],"correct":3,"exp":"Loans create a fixed repayment obligation but preserve ownership, unlike equity funding which shares ownership."},{"q":"What do lenders typically evaluate before approving a loan?","opts":["Cash flow, collateral, and credit history","Only the founder's personal popularity","Nothing; loans are approved automatically","The business's excitement about future growth alone"],"correct":0,"exp":"Lenders assess concrete indicators of repayment ability, such as cash flow, collateral, and credit history."},{"q":"What is a leading cause of financial distress related to loans?","opts":["Matching a loan to a specific, realistic use","Taking on debt beyond what the business can realistically repay","Never taking any loans at all","Repaying a loan too quickly"],"correct":1,"exp":"Borrowing more than the business can realistically repay from its actual cash flow is a common path to financial trouble."},{"q":"A founder compares loans using only the amount received. What else matters?","opts":["Only the lender's branding","Only the contract's page colour","Only the business slogan","Repayment schedule, total cost and obligations"],"correct":3,"exp":"Debt suitability depends on its full terms and cash repayment capacity."}]},
    {"key":"M10:Government Grants","rows":[{"q":"What distinguishes a government grant from a loan?","opts":["A grant always requires giving up equity","There is no real difference between a grant and a loan","A grant usually does not require scheduled loan repayment when its conditions are met","A grant must be repaid with interest"],"correct":2,"exp":"Grant terms define permitted spending and conditions; failure to meet them can lead to repayment obligations."},{"q":"What do grants typically require in exchange for funding?","opts":["Giving up majority ownership","Repaying the funds with interest","Nothing at all","Meeting specific conditions and reporting requirements tied to the grant's purpose"],"correct":3,"exp":"Grants usually come with specific conditions and reporting obligations tied to the goal they support."},{"q":"What improves a business's chance of a successful grant application?","opts":["The business's genuine goals actually aligning with the grant's specific purpose","Offering the grant provider equity","Avoiding any reporting requirements","Applying for every grant regardless of fit"],"correct":0,"exp":"A strong, genuine match between the business's actual mission and the grant's purpose improves the odds of a successful application."},{"q":"A grant offer restricts how funds may be used. What should the founder do?","opts":["Check eligibility, permitted spending and reporting conditions","Treat all funds as unrestricted personal cash","Assume conditions never matter","Spend first and hide the records"],"correct":0,"exp":"Grant funding must be managed under its actual award terms."}]},
    {"key":"M10:Investor Pitch Preparation","rows":[{"q":"What should a strong investor pitch typically cover?","opts":["Only the founder's personal background","The problem, solution, market size, business model, traction, team, and funding ask","Only the requested funding amount","Only competitor weaknesses"],"correct":1,"exp":"A complete pitch addresses the core elements an investor needs to evaluate the opportunity, not just one piece."},{"q":"How should a pitch handle risks and limitations?","opts":["Risks are irrelevant to an investor pitch","Hide them entirely to appear more attractive","Address them honestly, since overly polished pitches can raise investor suspicion","Only mention risks if directly asked"],"correct":2,"exp":"Honest acknowledgement of risks, alongside a plan to address them, tends to build more investor trust than concealment."},{"q":"What strengthens a pitch more than projections alone?","opts":["A longer slide deck","Avoiding any mention of the market size","Promising unlimited future growth with no evidence","Evidence of real traction, like actual customers or sales"],"correct":3,"exp":"Concrete evidence of real traction is generally more persuasive to investors than optimistic projections alone."},{"q":"A pitch includes a large market figure but no customer evidence. What should be strengthened?","opts":["Only the slide animation","Only the founder's portrait","Only an unsupported valuation","The demand evidence, business model and stated assumptions"],"correct":3,"exp":"A credible pitch needs evidence and a coherent business case."}]},
    {"key":"M11:Choosing a Business Structure","rows":[{"q":"What does a business structure primarily determine?","opts":["Personal liability, taxation, and decision-making rules","The colour scheme of the business's branding","The number of customers a business will have","The specific products a business sells"],"correct":0,"exp":"A business's legal structure shapes who is liable for debts, how profits are taxed, and how decisions are made."},{"q":"Is choosing a business structure a permanent, one-time decision?","opts":["Yes, it can never be changed once chosen","It may be changed under applicable procedures, with costs and consequences to review","Business structure has no legal significance","Only large companies are allowed to change structure"],"correct":1,"exp":"Changes depend on local law and can affect taxation, filings, contracts and continuity; review the actual requirements."},{"q":"What should guide the choice of structure?","opts":["Always choosing the most complex available option","The founder's favourite colour","The business's current size, risk level, and number of owners","Whichever structure sounds most impressive"],"correct":2,"exp":"Structure choice should reflect the real, current circumstances of the business, not appearance or arbitrary preference."},{"q":"A founder wants a legal structure suitable for local liability and ownership needs. What should be reviewed?","opts":["Only the structure with the most impressive name","Available local structures and qualified advice on their consequences","Only another country's tax table","Only a competitor's logo"],"correct":1,"exp":"Structure choices depend on local rules and the venture's circumstances."}]},
    {"key":"M11:Sole Proprietorship","rows":[{"q":"What defines a sole proprietorship?","opts":["Ownership shared equally among many shareholders","A structure that always requires government approval to start","A structure with no owner at all","No legal distinction between the owner and the business"],"correct":3,"exp":"A sole proprietorship has a single owner with no legal separation between them and the business."},{"q":"What is the major risk of a sole proprietorship?","opts":["Unlimited personal liability for business debts and claims","Extremely high setup cost","A legal requirement to have multiple owners","Automatic loss of all profits to the government"],"correct":0,"exp":"Because owner and business are not legally separate, personal assets can be at risk from business debts."},{"q":"Who is a sole proprietorship typically best suited for?","opts":["Businesses that never intend to earn any profit","Small, low-risk businesses, especially at an early stage","Only very large, multinational corporations","Businesses with hundreds of shareholders"],"correct":1,"exp":"Its simplicity and low cost make it a common fit for small, lower-risk businesses just getting started."},{"q":"A sole owner assumes registration alone always separates personal and business liability. What needs clarification?","opts":["Only the business card's wording","The actual liability position under the applicable structure and law","Only the website's domain","Only the owner's job title"],"correct":1,"exp":"Registration and separate legal personality are different questions."}]},
    {"key":"M11:Partnership","rows":[{"q":"What defines a partnership?","opts":["A structure available only to registered corporations","A type of government grant","A business owned by two or more people sharing responsibility, profit, and typically liability","A business owned by a single individual"],"correct":2,"exp":"A partnership involves shared ownership, operational responsibility and typically liability among two or more people."},{"q":"Why is a written partnership agreement important, even between close friends?","opts":["It is only required for partnerships with more than ten partners","Written agreements are illegal in most places","It has no real importance between trusted friends","Disagreements over money and control are more likely, and costly, once real business decisions are involved"],"correct":3,"exp":"Clear written terms help prevent disputes over profit sharing and decision-making from damaging both the business and the relationship."},{"q":"What does shared liability in a partnership typically mean?","opts":["One partner's decisions can create obligations for all partners","Each partner is only liable for their own personal actions outside the business","Partnerships have no liability at all","Liability applies only to the partner who founded the business"],"correct":0,"exp":"In many partnerships, obligations created by one partner can extend to the others, making shared liability significant."},{"q":"Two partners disagree about profit distribution and decision authority. What would reduce ambiguity?","opts":["Only a shared logo","Only a verbal promise to remain friends","Only a larger advertising budget","An appropriate agreement defining roles, rights and obligations"],"correct":3,"exp":"Partnership expectations should be clear and documented."}]},
    {"key":"M11:Corporation","rows":[{"q":"What is a defining feature of a corporation?","opts":["It is always owned by the government","It is legally separate from its owners","It has no legal existence apart from the founder","It cannot ever raise outside investment"],"correct":1,"exp":"A corporation exists as its own legal entity, distinct from its shareholders."},{"q":"What protection does a corporate structure typically provide owners?","opts":["Guaranteed profit regardless of performance","Full personal liability for every business decision","Limited liability, generally protecting personal assets from business debts","Complete exemption from all business risk"],"correct":2,"exp":"Because the corporation is a separate legal entity, owners' personal assets are generally shielded from business liabilities."},{"q":"What added requirements typically come with a corporate structure?","opts":["A requirement that only one person may ever own shares","A ban on ever raising outside investment","None; corporations require no additional formality","More formal registration, record-keeping, and governance requirements"],"correct":3,"exp":"Corporations typically involve more formal registration, record-keeping and governance than simpler business structures."},{"q":"A shareholder assumes a corporation can ignore all filing obligations. What should be checked?","opts":["Only its stationery","Only its social media pages","Only the shareholder's preferred title","Its applicable governance, reporting and compliance requirements"],"correct":3,"exp":"A separate entity still has legal and administrative obligations."}]},
    {"key":"M11:LLC","rows":[{"q":"What does LLC stand for?","opts":["Limited Liability Company","Licensed Local Corporation","Long-term Legal Contract","Limited Loan Certificate"],"correct":0,"exp":"LLC means Limited Liability Company. Its availability, governance and treatment depend on the applicable jurisdiction."},{"q":"What are LLC owners typically called?","opts":["Shareholders","Members","Directors only","Trustees"],"correct":1,"exp":"Owners of an LLC are generally referred to as members, rather than shareholders as in a corporation."},{"q":"Where an LLC is available, what should a founder compare when considering it against a corporation?","opts":["Because LLCs are only available to very large companies","Because LLCs cannot have more than one owner","The actual liability, governance, tax and filing requirements for each option","Because LLCs offer no liability protection at all"],"correct":2,"exp":"An LLC is not universally simpler or tax-favoured; suitability depends on its actual local rules and the venture's needs."},{"q":"A founder wants to use an LLC template from another jurisdiction. What should be verified first?","opts":["Only whether the template looks polished","Only the word 'limited' in the title","Local availability, legal requirements and suitable professional guidance","Only the proposed logo"],"correct":2,"exp":"LLC terminology and rules must be checked in the relevant jurisdiction."}]},
    {"key":"M11:Business Registration","rows":[{"q":"What is business registration?","opts":["A voluntary marketing activity","A one-time tax payment","A type of business loan","The formal process of recording a business with the relevant government authority"],"correct":3,"exp":"Registration formally establishes a business's legal recognition to operate under its name and structure."},{"q":"What practical benefit does proper registration often provide?","opts":["Easier access to a business bank account and formal credit","Automatic exemption from all future taxes","Guaranteed profitability","No practical benefit at all"],"correct":0,"exp":"Registration is often required before banks or lenders will extend business banking or credit access."},{"q":"Do registration requirements vary by country and structure?","opts":["No, requirements are identical everywhere","Yes, both country and chosen business structure affect requirements","Only the business's name affects requirements","Registration requirements never change"],"correct":1,"exp":"Both the country's regulations and the specific business structure chosen shape what registration actually involves."},{"q":"A founder finds conflicting registration instructions on old blogs. What should guide the next step?","opts":["Only the cheapest unofficial package","Current information from the relevant official registry","Only the oldest article","Only a competitor's past receipt"],"correct":1,"exp":"Registration procedures should be verified against current official requirements."}]},
    {"key":"M11:Licenses & Permits","rows":[{"q":"How do licenses and permits differ from general business registration?","opts":["They replace the need for business registration entirely","They are the exact same thing","They are additional, industry- or activity-specific approvals beyond general registration","Licenses are only needed by government agencies themselves"],"correct":2,"exp":"Licenses and permits are specific, additional approvals tied to a particular industry or activity, distinct from general registration."},{"q":"What risk comes from operating without a required license?","opts":["Automatic approval of the license after the fact","Only a minor inconvenience","No risk, as long as the business is otherwise legitimate","Fines, forced closure, or legal liability"],"correct":3,"exp":"Operating without a legally required license can lead to real financial and operational consequences, including forced closure."},{"q":"Why should required licenses be identified before launch?","opts":["To avoid costly, preventable problems discovered later, such as during an inspection","Licenses can always be obtained instantly at any time","It has no effect on when a business can open","Licenses are never actually required in practice"],"correct":0,"exp":"Identifying licensing needs before opening avoids disruptive, avoidable problems like a forced closure after the fact."},{"q":"A registered venture enters a regulated activity it has not checked. What must be investigated?","opts":["Only whether its logo is registered","Only the size of its website","Only its bank's name","The additional permits and approvals for that activity and location"],"correct":3,"exp":"General registration does not establish every activity-specific permission."}]},
    {"key":"M11:Taxes","rows":[{"q":"What are business taxes?","opts":["Payments made only by very large corporations","Legally required payments to government based on income, sales, or other activity","Voluntary donations a business may choose to make","A type of business loan"],"correct":1,"exp":"Taxes are mandatory government payments tied to a business's income, sales, property, or other taxable activity."},{"q":"What is the foundation of accurate, manageable tax filing?","opts":["Avoiding any financial record-keeping","Hiring an accountant only once, at the very start","Accurate bookkeeping maintained throughout the year","Reconstructing all records right before the deadline"],"correct":2,"exp":"Because filings rely entirely on financial records, consistent bookkeeping throughout the year makes tax time far easier and more accurate."},{"q":"What can result from missing tax obligations or deadlines?","opts":["An automatic tax refund","A permanent exemption from future taxes","No consequences at all","Penalties, interest, or legal consequences"],"correct":3,"exp":"Failing to meet tax obligations or deadlines can lead to real financial penalties and legal consequences."},{"q":"A founder copies a tax rate from a foreign startup guide. What should happen before relying on it?","opts":["Use it because all countries have identical taxes","Change only the currency symbol","Verify applicable current local rules with official guidance or qualified help","Apply it only to the largest invoice"],"correct":2,"exp":"Tax obligations depend on the applicable jurisdiction and circumstances."}]},
    {"key":"M11:Intellectual Property","rows":[{"q":"What does intellectual property protect?","opts":["Original creations of the mind, like inventions, designs, and creative works","Only a business's cash reserves","Only government-owned assets","Only a business's physical inventory"],"correct":0,"exp":"IP law protects original, creative and inventive output, recognising it as valuable in its own right, distinct from physical goods."},{"q":"What is the first step to protecting a business's intellectual property?","opts":["Ignoring the issue until a competitor copies something","Identifying which assets are genuinely protectable IP","Registering every possible type of IP regardless of relevance","Assuming all ideas are automatically protected with no action needed"],"correct":1,"exp":"Recognising which specific assets qualify as protectable IP is necessary before pursuing the right kind of protection."},{"q":"Why should a founder review protection requirements separately for each type of intellectual property?","opts":["The idea automatically becomes public property, which is beneficial","It has no bearing on a business's success","Different rights have different eligibility, registration and enforcement rules","Nothing; formal protection has no real effect"],"correct":2,"exp":"Some rights can arise automatically, while others need registration; protection should be assessed for the specific asset."},{"q":"A founder assumes every idea is automatically protected in the same way. What should be distinguished?","opts":["The specific asset and relevant form of protection","Only the asset's file size","Only the founder's favourite slogan","Only the business's cash balance"],"correct":0,"exp":"Different creations and identifiers can involve different IP rights."}]},
    {"key":"M11:Trademarks & Copyrights","rows":[{"q":"What does a trademark protect?","opts":["Original written or artistic works","A business's physical inventory","A business's tax records","Brand identifiers like a name, logo, or slogan"],"correct":3,"exp":"Trademarks specifically protect the identifiers that distinguish a business's brand in the marketplace."},{"q":"When does copyright protection typically begin?","opts":["Automatically, from the moment an original work is created in a fixed form","Only after the work is sold commercially","Copyright protection never applies automatically","Only after formal government registration is completed"],"correct":0,"exp":"Copyright generally arises automatically for qualifying original works in Berne Convention countries. Exact eligibility and enforcement rules vary."},{"q":"Does formally registering a trademark generally strengthen protection?","opts":["No, registration has no legal effect","Yes, it generally strengthens protection and eases enforcement against imitators","Registration actually weakens trademark rights","Trademarks cannot be registered under any circumstances"],"correct":1,"exp":"Formal registration typically provides stronger legal standing and easier enforcement compared to relying on informal use alone."},{"q":"A startup wants to protect its brand name and an original written guide. What should it recognise?","opts":["They are both automatically patents","A domain purchase grants all rights worldwide","Every protection requires the same process","Brand identifiers and creative expression involve different types of rights"],"correct":3,"exp":"Trademark and copyright serve different protective purposes."}]},
    {"key":"M11:Contracts","rows":[{"q":"What is a contract?","opts":["A type of business tax filing","A marketing document","A legally binding agreement specifying obligations, terms, and consequences","An informal, unenforceable conversation"],"correct":2,"exp":"A contract is a legally binding agreement that clearly defines each party's obligations and the consequences of not meeting them."},{"q":"What makes a contract's terms effective?","opts":["Leaving out any consequences for failing to meet terms","Relying only on a verbal handshake","Being as vague as possible to allow flexibility","Being specific and unambiguous about deliverables, deadlines, and payment"],"correct":3,"exp":"Specific, clear terms leave little room for the kind of misunderstanding that leads to disputes."},{"q":"What risk do verbal-only agreements create?","opts":["Ambiguity that can become costly if a dispute arises","They are automatically more legally binding than written contracts","They eliminate the need for any trust between parties","No risk; verbal agreements are just as reliable as written ones"],"correct":0,"exp":"Without a clear written record, verbal agreements can lead to disputes over exactly what was promised."},{"q":"A supplier agreement promises 'quick delivery' with no defined deadline. What should be clarified?","opts":["Only the document's colour","Only the supplier's logo","Specific delivery obligations, timing and agreed remedies","Only the filename"],"correct":2,"exp":"Clear terms help parties understand and review their obligations."}]},
    {"key":"M12:Business Operations","rows":[{"q":"What are business operations?","opts":["Only financial record-keeping","The day-to-day activities that turn plans into delivered products or services","Only the marketing plan of a business","Only the founder's personal responsibilities"],"correct":1,"exp":"Operations cover the practical, ongoing work of actually producing and delivering what a business promises."},{"q":"What matters most for strong operations?","opts":["Doing things differently every single time","Occasional excellence with inconsistent everyday quality","Consistency &mdash; the same quality and reliability every time","Focusing only on marketing and ignoring delivery"],"correct":2,"exp":"Reliable, predictable quality every time builds more trust than occasional excellence paired with inconsistency."},{"q":"What can happen when strategy is strong but operations are weak?","opts":["Operations have no effect on customer experience","The business automatically becomes more profitable","Customers always remain satisfied regardless","The actual customer experience suffers, undermining the value of the strategy"],"correct":3,"exp":"A good plan poorly executed operationally still results in a disappointing experience for the actual customer."},{"q":"Orders grow but fulfilment responsibilities are unclear. What should operations planning define?","opts":["Only a more exciting company slogan","The workflow, resources, owners and performance checks","Only the office's decoration","Only a larger sales target"],"correct":1,"exp":"Operations need a practical system for delivering the promise."}]},
    {"key":"M12:Supply Chain","rows":[{"q":"What is a supply chain?","opts":["The network of suppliers, transport, and processes moving goods from origin to customer","Only a business's marketing plan","Only the business's financial records","A term that only applies to large international companies"],"correct":0,"exp":"A supply chain spans every step involved in getting materials or goods to the final customer, regardless of business size."},{"q":"What creates real vulnerability in a supply chain?","opts":["Having multiple backup suppliers available","Relying entirely on a single supplier or route with no alternative","Reviewing supplier performance regularly","Diversifying transportation options"],"correct":1,"exp":"Depending on just one supplier or route, with no backup, leaves a business exposed if that single link fails."},{"q":"What reduces the risk of a single point of failure in a supply chain?","opts":["Using only the cheapest available supplier regardless of reliability","Assuming disruptions will never happen","Having at least one backup supplier or route arranged in advance","Ignoring supply chain risk entirely"],"correct":2,"exp":"A backup option, arranged before it is needed, lets a business absorb a disruption instead of being forced to stop serving customers."},{"q":"A critical input depends on a supplier with frequent delays. What should be assessed?","opts":["Only the supplier's letterhead","Only its longest product name","Only the founder's preferred colour","Lead times, contingency options and the effect on delivery"],"correct":3,"exp":"Supply reliability affects the venture's ability to serve customers."}]},
    {"key":"M12:Inventory Management","rows":[{"q":"What is inventory management?","opts":["Only managing a business's cash reserves","Only tracking customer complaints","A marketing activity","Tracking and controlling the stock a business holds"],"correct":3,"exp":"Inventory management involves tracking and controlling stock across raw materials, work-in-progress, and finished goods."},{"q":"What is a risk of excess inventory?","opts":["It ties up cash and risks spoilage or obsolescence","It has no downside at all","It always improves customer satisfaction","It guarantees higher profit"],"correct":0,"exp":"Holding more inventory than needed locks up cash and risks the stock becoming spoiled, damaged, or outdated."},{"q":"What does accurate, ongoing inventory tracking allow a founder to do?","opts":["Guarantee zero future stockouts with no effort","Order more of what actually sells and reduce over-ordering of what does not","Ignore customer demand entirely","Avoid the need for any bookkeeping"],"correct":1,"exp":"Reliable, current tracking data lets a founder make smarter, demand-matched ordering decisions."},{"q":"Stock records show availability but actual shelves are empty. What should be reviewed?","opts":["Only the sales poster","Only the warehouse's logo","Recording accuracy, reconciliation and replenishment controls","Only the website's font"],"correct":2,"exp":"Inventory information needs to match physical stock."}]},
    {"key":"M12:Procurement","rows":[{"q":"What is procurement?","opts":["A method of managing employee performance","A tax filing requirement","The process of sourcing and purchasing the goods and services a business needs","A marketing strategy for attracting customers"],"correct":2,"exp":"Procurement covers deliberately sourcing and purchasing the materials, goods, and services a business relies on."},{"q":"What should good procurement balance?","opts":["Only the supplier's location","Only the size of the supplier's company","Price alone, always choosing the cheapest option","Price, quality, and supplier reliability together"],"correct":3,"exp":"Sound procurement weighs price alongside quality and reliability, rather than optimising for price in isolation."},{"q":"What can constantly switching suppliers for the lowest price cost a business?","opts":["Consistency in quality and reliability during shortages","It guarantees better long-term relationships","It has no effect on quality or reliability","Nothing; it always produces the best outcome"],"correct":0,"exp":"Chasing the cheapest price each time can sacrifice the consistency and flexibility a stable supplier relationship provides."},{"q":"The cheapest supplier quote omits transport and maintenance costs. What should be compared?","opts":["Only the headline purchase price","Only the quote's colour","Only the salesperson's confidence","Total relevant cost, quality and service conditions"],"correct":3,"exp":"Procurement decisions should consider the full usable offer."}]},
    {"key":"M12:Business Systems","rows":[{"q":"What is a business system?","opts":["A marketing campaign","A documented, repeatable way of carrying out a recurring process","A one-time decision made by the founder","A type of financial loan"],"correct":1,"exp":"A business system captures a process in a repeatable, documented form so it can be performed consistently by anyone."},{"q":"What problem do systems solve?","opts":["The requirement to ever hire employees","The need for accurate bookkeeping","Dependence on one specific person's memory or presence","The need for any customer service at all"],"correct":2,"exp":"Systems remove reliance on a single individual, allowing consistent execution even when that person is unavailable."},{"q":"Where is it most efficient to start building business systems?","opts":["Systems should never be prioritised in any particular order","Only after the business has stopped growing","With the least important, rarely performed tasks","With the most repeated, highest-impact tasks first"],"correct":3,"exp":"Focusing first on frequent, high-impact processes delivers the most value for the effort of documenting a system."},{"q":"A business depends on the founder remembering every order. What system would help?","opts":["Only a larger desk calendar image","A reliable recorded workflow with ownership and checks","Only a motivational poster","Only more undocumented verbal instructions"],"correct":1,"exp":"Systems reduce dependence on one person's memory."}]},
    {"key":"M12:Standard Operating Procedures (SOPs)","rows":[{"q":"What is a Standard Operating Procedure?","opts":["A specific, step-by-step written instruction for carrying out one task","A general company mission statement","A type of financial report","A marketing slogan"],"correct":0,"exp":"An SOP details the exact steps for performing one specific task correctly and consistently."},{"q":"What makes an SOP good?","opts":["Being vague enough to allow personal interpretation","Being detailed enough for someone unfamiliar with the task to follow correctly","Never being updated once written","Being written only for experienced staff"],"correct":1,"exp":"An effective SOP is specific and clear enough that even someone new to the task can perform it correctly."},{"q":"Why is an outdated, ignored SOP worse than having none at all?","opts":["It has no negative effect","It is not worse; outdated SOPs are always still useful","Staff learn to distrust written instructions generally, undermining future documentation efforts","Outdated SOPs are illegal"],"correct":2,"exp":"An outdated SOP that staff learn to ignore can erode trust in written procedures overall, undermining documentation efforts more broadly."},{"q":"New staff perform the same task inconsistently because instructions are vague. What should an SOP provide?","opts":["Only the company's history","Only the manager's signature","Clear steps, responsibilities and expected standards","Only the task's nickname"],"correct":2,"exp":"An SOP should make repeatable work understandable."}]},
    {"key":"M12:Risk Management","rows":[{"q":"What is risk management?","opts":["Ignoring risks until they actually occur","A type of marketing plan","A method for increasing sales","Identifying potential threats and deciding deliberately how to address them"],"correct":3,"exp":"Risk management means proactively identifying and addressing potential threats, rather than only reacting after they occur."},{"q":"What two factors should guide how a risk is assessed?","opts":["Its likelihood and its potential severity of impact","Only how much it would cost to fix after it happens","Only the founder's personal opinion","Only whether competitors face the same risk"],"correct":0,"exp":"Weighing both how likely a risk is and how severe its consequences would be gives a fuller, more useful assessment."},{"q":"Why might a rare risk deserve significant preparation?","opts":["Rare risks never deserve any preparation","If its potential impact is severe enough, even a rare risk can justify proactive preparation","Rare risks are always less important than common ones","Preparation is only useful for risks that happen frequently"],"correct":1,"exp":"A low-probability but high-impact risk can still warrant serious preparation, since its consequences could be severe if it occurs."},{"q":"A risk register lists hazards without assigning action owners. What is missing?","opts":["Only a longer report title","Responsibility for prevention, response and monitoring","Only more decorative icons","Only the founder's biography"],"correct":1,"exp":"Risk management needs practical accountable action."}]},
    {"key":"M12:Business Continuity","rows":[{"q":"What does business continuity planning prepare a business to do?","opts":["Avoid ever needing to identify any risks","Only respond to minor, everyday inconveniences","Keep operating, or recover quickly, through a serious disruption","Guarantee no disruption will ever occur"],"correct":2,"exp":"Continuity planning specifically prepares a business to continue functioning or recover quickly during a serious disruption."},{"q":"What should a continuity plan identify?","opts":["Only the business's marketing budget","Only the founder's personal daily schedule","Only the business's tax obligations","The business's most essential functions that must continue even in a crisis"],"correct":3,"exp":"A continuity plan focuses on protecting the functions most critical to the business's survival during a disruption."},{"q":"Why should a continuity plan be tested or reviewed occasionally?","opts":["It reveals gaps in the plan before a real crisis exposes them","It is a legal requirement in every country","It guarantees the disruption will never happen","Testing has no value once a plan is written"],"correct":0,"exp":"Reviewing or testing a plan in advance can surface weaknesses while there is still time to fix them, rather than during an actual crisis."},{"q":"A power outage stops a venture's essential service. What should a continuity plan specify?","opts":["Only a larger advertisement","Only a new company name","How critical operations can continue or recover safely","Only a promise that outages cannot occur"],"correct":2,"exp":"Continuity planning prepares for plausible operational disruption."}]},
    {"key":"M13:Hiring Employees","rows":[{"q":"What should hiring start from?","opts":["Waiting until the business is in crisis","A clearly defined need and the specific skills it requires","Hiring whoever applies first, regardless of fit","Only the candidate's personal connections"],"correct":1,"exp":"Starting from a clear, specific need helps match the right skills and qualities to the actual gap in the business."},{"q":"What often results from reactive, pressured hiring?","opts":["Guaranteed long-term employee retention","Consistently excellent hiring decisions","Rushed, poorly matched hiring decisions","No effect on hiring quality at all"],"correct":2,"exp":"Hiring under pressure, without proper planning, tends to produce mismatches between the role and the person hired."},{"q":"What can a poor hire cost a business?","opts":["Only a minor, easily recovered inconvenience","It always benefits the business regardless of fit","Nothing beyond the employee's salary","Significant wasted time, training effort, and morale, often beyond the salary itself"],"correct":3,"exp":"A mismatched hire can cost far more in lost time, retraining, and team morale than the visible salary cost alone."},{"q":"A founder hires before defining the work the role must perform. What should be clarified?","opts":["Only the employee's job-title style","Only the company's profile image","Only a larger recruitment slogan","The role's responsibilities, required skills and practical employment terms"],"correct":3,"exp":"Hiring should follow a clear role and operating need."}]},
    {"key":"M13:Recruitment","rows":[{"q":"What distinguishes recruitment from simply posting a vacancy?","opts":["Recruitment is an active process of finding and attracting candidates, not just waiting for applications","Recruitment means only hiring people who apply first","There is no meaningful difference","Recruitment only applies to large companies"],"correct":0,"exp":"Active recruitment goes beyond posting a vacancy, seeking out strong candidates directly rather than waiting passively."},{"q":"Why reach candidates who are not actively job-searching?","opts":["It has no advantage over passive posting","It can uncover strong candidates that competitors relying only on postings might miss","It is illegal to contact non-applicants","Such candidates are never a good fit"],"correct":1,"exp":"Proactively reaching potential candidates widens access to strong talent beyond those already actively searching."},{"q":"What does an honest, accurate job description help achieve?","opts":["Guaranteeing every applicant is qualified","Nothing meaningful for the hiring outcome","Attracting candidates who are a genuine fit and reducing early mismatched-expectation turnover","Discouraging all applicants from applying"],"correct":2,"exp":"Accurate descriptions help candidates self-select based on genuine fit, reducing turnover caused by mismatched expectations."},{"q":"Applicants are compared using different improvised questions. What would make selection more consistent?","opts":["Only the applicant's social follower count","Only the longest CV","Only the interviewer's personal similarity","Relevant role criteria and a structured assessment process"],"correct":3,"exp":"A consistent process supports a more defensible comparison."}]},
    {"key":"M13:Team Building","rows":[{"q":"What is team building?","opts":["Only organising social events for staff","A one-time hiring activity","A financial planning process","The deliberate effort to help a group of individuals function as a cohesive, effective team"],"correct":3,"exp":"Team building is the intentional work of shaping individuals into a group that trusts and communicates well together."},{"q":"What helps reduce friction within a team?","opts":["Clear shared goals and well-defined roles that avoid overlap or confusion","Avoiding all regular communication","Assigning every task to only one person","Leaving roles undefined so people can decide for themselves"],"correct":0,"exp":"Clarity about goals and individual roles reduces the confusion and duplicated effort that often causes team friction."},{"q":"Is getting along socially the same as functioning well as a working team?","opts":["Yes, they are identical","No, effective teamwork also requires clear goals, roles, and communication","Social connection has no relevance to teamwork at all","Teams cannot function well if members like each other"],"correct":1,"exp":"Genuine teamwork requires structural elements like clear goals and roles, beyond simply getting along personally."},{"q":"Team members complete tasks but rarely share information needed by others. What should improve?","opts":["Only the team's matching shirts","Only the leader's title","Only the meeting-room decoration","Shared goals, communication and coordination"],"correct":3,"exp":"Team effectiveness requires coordination around shared outcomes."}]},
    {"key":"M13:Leadership","rows":[{"q":"What does leadership involve beyond simply assigning tasks?","opts":["Avoiding any interaction with the team","Only handling financial decisions","Setting direction, building trust, and modelling expected standards through behaviour","Only issuing detailed instructions for every task"],"correct":2,"exp":"Leadership includes shaping direction, earning trust, and demonstrating standards through one's own conduct, not just task assignment."},{"q":"Does one leadership style fit every situation?","opts":["Leadership style has no effect on outcomes","Only direct instruction is ever effective","Yes, a single consistent style always works best","No, different situations call for different leadership approaches"],"correct":3,"exp":"Effective leadership adapts to context, sometimes directing closely and other times empowering the team's own judgment."},{"q":"What often makes a team willing to follow a leader through difficulty?","opts":["Genuine trust built over time","Strict rules with no flexibility","Avoiding any communication with the team","Fear of consequences alone"],"correct":0,"exp":"Trust, built through consistent and fair leadership, is often what motivates a team to stay committed during hard periods."},{"q":"A team avoids reporting problems because its leader punishes every concern. What should change?","opts":["Demand that all reports be positive","Create a process for honest reporting and constructive action","Hide operational results","Replace all feedback with slogans"],"correct":1,"exp":"Useful leadership needs accurate information and accountable responses."}]},
    {"key":"M13:Company Culture","rows":[{"q":"What is company culture?","opts":["A marketing slogan displayed publicly","The shared, often unwritten norms and values shaping actual day-to-day behaviour","Only the official written mission statement","A type of financial report"],"correct":1,"exp":"Culture reflects the real, lived norms and values that shape behaviour, which can differ from any official statement."},{"q":"What primarily builds a company's culture?","opts":["A one-time company memo","Culture cannot be built or shaped at all","Consistent lived example, especially from leadership","Posters and slogans alone"],"correct":2,"exp":"Actual, consistent behaviour &mdash; particularly from leaders &mdash; shapes culture far more than stated values or slogans."},{"q":"Can a toxic culture drive away good employees even with competitive pay?","opts":["Culture has no effect on employee retention","Only new employees are affected by culture","No, pay always outweighs culture","Yes, a toxic culture can drive good employees away regardless of compensation"],"correct":3,"exp":"Even strong pay often cannot compensate for a genuinely toxic or unhealthy working culture, and good employees may leave regardless."},{"q":"A venture claims to value quality but rewards rushing unchecked work. What should be aligned?","opts":["Only the office wall's wording","Incentives and everyday behaviour with the stated values","Only the website's colour","Only the founder's portrait"],"correct":1,"exp":"Culture is reinforced by actual decisions and behaviours."}]},
    {"key":"M13:Employee Performance","rows":[{"q":"What does managing employee performance involve?","opts":["Regularly assessing expectations and providing improving feedback","Only reacting when something goes seriously wrong","Ignoring performance entirely until an annual review","Only tracking financial output"],"correct":0,"exp":"Good performance management is an ongoing process of assessment and constructive feedback, not just crisis response."},{"q":"What makes feedback most effective?","opts":["Being vague, delayed, and only negative","Being specific, timely, and balanced between strengths and areas to improve","Saving all feedback for one annual review","Avoiding ever acknowledging good performance"],"correct":1,"exp":"Specific, timely, balanced feedback helps an employee understand and act on it far more effectively than vague or delayed comments."},{"q":"Why is feedback given close to the actual event more useful than annual feedback?","opts":["Annual feedback is always more accurate","Timely feedback is illegal in most workplaces","Because details are harder to recall and act on if feedback is delayed","There is no difference in usefulness"],"correct":2,"exp":"Feedback given soon after an event is easier for both parties to recall clearly and act on than delayed, saved-up feedback."},{"q":"An employee receives criticism without knowing the expected result. What should be defined?","opts":["Only a more impressive job title","Clear achievable expectations and evidence-based feedback","Only the supervisor's preferences","Only longer working hours regardless of output"],"correct":1,"exp":"Performance review needs understandable expectations."}]},
    {"key":"M13:Payroll Basics","rows":[{"q":"What does payroll involve?","opts":["Only setting the visible salary amount","Only marketing to attract new customers","A type of customer service activity","Calculating and distributing employee pay, deductions, and related tax obligations"],"correct":3,"exp":"Payroll spans the full calculation and distribution of pay along with deductions and statutory obligations."},{"q":"Why does accurate, on-time payroll matter for employee trust?","opts":["Consistent, correct pay is a foundational way a business earns and keeps employee trust","Employees never notice payroll errors","Payroll only matters for very large companies","It has no effect on how employees feel about the business"],"correct":0,"exp":"Reliable, accurate pay is one of the most basic and important ways a business demonstrates it can be trusted by its employees."},{"q":"What can result from payroll mistakes, even unintentional ones?","opts":["Guaranteed tax exemption","Real legal and financial exposure for the business","No consequences at all","Automatic praise from employees"],"correct":1,"exp":"Even unintentional payroll errors can create genuine compliance and financial risk for a business."},{"q":"Payroll deductions are copied from an outdated spreadsheet without verification. What should be checked?","opts":["Only the spreadsheet's border colour","Current applicable requirements and accurate approved pay records","Only the employee's nickname","Only the file's storage size"],"correct":1,"exp":"Payroll requires valid inputs and current applicable rules."}]},
    {"key":"M13:Conflict Resolution","rows":[{"q":"What is conflict resolution?","opts":["Automatically siding with whoever raised the issue first","A type of financial planning process","Addressing workplace disagreements fairly and directly, aiming at a genuine solution","Avoiding any disagreement entirely"],"correct":2,"exp":"Effective conflict resolution means engaging with disagreements directly and fairly, rather than avoiding or prematurely judging them."},{"q":"What tends to happen to unresolved workplace conflict?","opts":["It has no effect on the wider team","It only affects the business's finances","It always resolves itself naturally over time","It tends to grow and affect team morale beyond just the people directly involved"],"correct":3,"exp":"Left unaddressed, conflict often intensifies and can quietly damage morale and performance across the wider team."},{"q":"What approach tends to produce a more durable resolution?","opts":["Finding a solution both parties can genuinely accept","Ignoring one side's perspective entirely","Focusing only on personal character rather than the specific issue","Declaring a clear winner and loser"],"correct":0,"exp":"A solution both sides genuinely accept tends to hold up better over time than one side simply being declared right."},{"q":"Two employees disagree about who should complete a shared task. What is a constructive first step?","opts":["Publicly blame whichever person speaks last","Ignore the conflict indefinitely","Clarify the facts, responsibilities and underlying concerns","Change only the task's name"],"correct":2,"exp":"Resolution starts with understanding the issue and responsibilities."}]},
    {"key":"M14:AI in Business","rows":[{"q":"What is AI in a business context?","opts":["A legal business structure","Software performing tasks normally requiring human judgment, often faster and cheaper","Only physical machinery used in manufacturing","A type of business loan"],"correct":1,"exp":"AI tools handle tasks like writing, analysis, and answering questions that would otherwise require manual human effort."},{"q":"Where is AI typically most valuable for a small business?","opts":["Only for tasks requiring no review at all","Completely replacing all human judgment across the business","Specific, repetitive tasks, freeing the founder's time for higher-value work","Only for very large corporations"],"correct":2,"exp":"AI adds the most practical value on defined, repetitive tasks, complementing rather than replacing human judgment."},{"q":"Should AI-generated output be used without review?","opts":["Review is only needed for financial documents","AI output requires no human involvement at all","Yes, AI output is always fully accurate","No, it should still be reviewed and verified before use"],"correct":3,"exp":"AI tools can make mistakes, so reviewing and verifying their output before relying on it remains important."},{"q":"An AI workflow saves time but introduces errors into customer messages. What should be assessed?","opts":["Only the number of generated words","Its net usefulness, oversight and error controls","Only the tool's novelty","Only the founder's excitement"],"correct":1,"exp":"Automation should improve reliable outcomes rather than only speed."}]},
    {"key":"M14:ChatGPT for Entrepreneurs","rows":[{"q":"What kind of prompts tend to produce the most useful AI responses?","opts":["Specific, detailed prompts including relevant business context and a clear goal","Requests with no clear goal stated","Only single-word questions","Vague, general requests with no context"],"correct":0,"exp":"Detailed, specific prompts that include real context produce far more useful, tailored answers than vague requests."},{"q":"How should a founder treat AI-drafted content?","opts":["As a final, unreviewed source of truth","As a useful first draft or starting point, to be reviewed before use","As something that should never be used","As identical to hiring a full-time employee"],"correct":1,"exp":"AI output is best treated as a helpful starting draft that still benefits from human review and refinement."},{"q":"What should a founder be careful about when using a conversational AI tool?","opts":["Reviewing the AI's output before use","Iterating on a request to improve the result","Sharing sensitive or confidential business information without understanding how it is handled","Using specific prompts"],"correct":2,"exp":"Because such tools process and may retain input, a founder should be thoughtful about sharing sensitive information."},{"q":"A founder uses an AI-generated market estimate without checking its source. What is required?","opts":["Treat fluent wording as proof","Make the figure larger in the pitch","Verify the evidence before relying on the estimate","Remove the source field"],"correct":2,"exp":"AI-generated business claims need independent verification."}]},
    {"key":"M14:Business Automation","rows":[{"q":"What is business automation?","opts":["Hiring more staff to do repetitive tasks manually","A type of financial loan","A marketing strategy","Using software to perform repetitive tasks automatically"],"correct":3,"exp":"Automation replaces manual, repeated human effort on a task with software that performs it automatically."},{"q":"What kind of tasks benefit most from automation?","opts":["Frequent, repetitive, rule-based tasks that follow the same steps every time","Tasks that happen only once a year","Tasks with no clear repeatable process","Tasks requiring constant, unique human judgment each time"],"correct":0,"exp":"Automation works best where the same steps repeat reliably, without needing fresh human judgment each time."},{"q":"Why should automated tasks still be checked periodically?","opts":["Automation is only ever used once and then discarded","Incorrect rules can cause the same error to repeat, unnoticed, every time","Automated tasks never need any oversight once set up","Checking automation has no value"],"correct":1,"exp":"Since automation repeats the same steps exactly, a flawed rule can quietly cause the same mistake repeatedly if left unchecked."},{"q":"An automated invoice process repeatedly bills customers incorrectly. What should happen?","opts":["Increase the automation speed","Correct the rules and verify the workflow before further use","Hide the complaints","Only rename the process"],"correct":1,"exp":"An efficient workflow must still produce correct results."}]},
    {"key":"M14:Website Creation","rows":[{"q":"Why does a website matter for many businesses today?","opts":["Websites are only relevant for large corporations","A website has no effect on customer trust","It is often a potential customer's first, and sometimes only, impression of the business","Customers never look at a business's website"],"correct":2,"exp":"For many customers, the website is the first point of contact and shapes their initial impression of the business."},{"q":"What matters more than visual complexity for a website?","opts":["Having as many features as possible","Using the most elaborate design available","Loading time has no real importance","Clarity, speed, and mobile usability"],"correct":3,"exp":"A clear, fast, mobile-friendly site serves customers better than an elaborate but slow or confusing one."},{"q":"What can happen if a website loads slowly on mobile phones?","opts":["Customers may leave before ever seeing what the business offers","It has no effect on customer behaviour","It automatically improves search ranking","Customers will always wait patiently regardless"],"correct":0,"exp":"Slow loading, especially on mobile, can cause potential customers to leave before engaging with the business's actual offer."},{"q":"A venture's website looks polished but its enquiry form fails. What should be verified?","opts":["Only the header image","The complete customer enquiry path and feedback","Only the domain's spelling length","Only the footer colour"],"correct":1,"exp":"A business website must support its intended practical tasks."}]},
    {"key":"M14:E-commerce","rows":[{"q":"What does e-commerce allow a business to do?","opts":["Guarantee sales without any marketing effort","Buy and sell goods or services online, reaching beyond a physical location","Only sell to customers who visit in person","Avoid the need for any product descriptions"],"correct":1,"exp":"E-commerce extends a business's reach to customers beyond those who can physically visit its location."},{"q":"What helps convert online interest into an actual sale?","opts":["Making payment as complicated as possible","Ignoring delivery reliability entirely","Clear photos, honest descriptions, easy payment, and reliable delivery","Avoiding any product descriptions"],"correct":2,"exp":"These practical elements build the trust and convenience needed for an online visitor to actually complete a purchase."},{"q":"Why is trust especially important in e-commerce?","opts":["Trust has no relevance to online sales","Online customers never have any concerns about quality","E-commerce transactions require no payment information","Customers cannot physically inspect a product before buying online"],"correct":3,"exp":"Since buyers cannot examine the product directly, clear and honest information plays an outsized role in building trust."},{"q":"An online shop shows stock that cannot be delivered. What needs integration?","opts":["Only a larger checkout banner","Product availability, order handling and fulfilment information","Only a different logo","Only the number of page animations"],"correct":1,"exp":"Online selling must connect accurately to actual operations."}]},
    {"key":"M14:Online Payment Systems","rows":[{"q":"What do online payment systems allow a business to do?","opts":["Accept payment electronically, beyond requiring in-person cash","Only accept payment from large corporations","Avoid the need for any bookkeeping","Guarantee zero transaction fees"],"correct":0,"exp":"These systems let a business accept payment through mobile money, cards, or digital wallets, not only cash."},{"q":"Why does matching payment options to customer preference matter?","opts":["Offering fewer payment options always increases sales","It reduces friction at checkout and can prevent abandoned purchases","Payment method has no effect on whether a sale completes","Customers never have a preferred payment method"],"correct":1,"exp":"Providing payment methods customers already prefer and trust makes it easier for them to complete a purchase."},{"q":"What matters as much as convenience in online payment systems?","opts":["Having only one single payment option","Avoiding any mention of transaction fees","Security and reliability of the payment process","The colour of the payment button"],"correct":2,"exp":"Customers and businesses both need confidence that payments are handled securely and processed reliably."},{"q":"A checkout declares payment successful based only on the browser's message. What should confirm it?","opts":["Only the button's colour","Only an unverified customer screenshot","Only the page's loading animation","A trusted verified transaction record from the payment system"],"correct":3,"exp":"Payment status should be based on reliable transaction verification."}]},
    {"key":"M14:CRM Software","rows":[{"q":"What does CRM software do?","opts":["Only manages employee payroll","Only handles a business's tax filings","A type of marketing advertisement","Systematically tracks customer information, interactions, and sales activity"],"correct":3,"exp":"CRM software organises customer data and activity in one place, beyond what manual tracking can handle at scale."},{"q":"When does CRM software become especially valuable?","opts":["As a customer base grows beyond what a spreadsheet can practically manage","Only for businesses with a single customer","CRM software has no added value at any size","Only after a business has permanently stopped growing"],"correct":0,"exp":"Its organisational and automation benefits become more valuable as the volume of customers and interactions grows."},{"q":"What can automated CRM reminders help prevent?","opts":["Legal registration requirements","A prospect being quietly forgotten and a potential sale being missed","Any need for customer service","The need for accurate bookkeeping"],"correct":1,"exp":"Automatic follow-up reminders help ensure prospects are not overlooked, preserving potential sales that might otherwise be lost."},{"q":"A CRM exposes every customer's records to unrelated users. What should be reviewed?","opts":["Access permissions and appropriate handling of customer information","Only the dashboard's colour","Only the vendor's slogan","Only the import filename"],"correct":0,"exp":"Customer records require suitable access controls."}]},
    {"key":"M14:Productivity Tools","rows":[{"q":"What are productivity tools?","opts":["A type of financial loan","A marketing strategy","Software that helps organise tasks, deadlines, and collaboration","Only physical office equipment"],"correct":2,"exp":"These tools support organisation, task tracking, and collaboration for a founder and team as the business grows."},{"q":"What matters more for a productivity tool's real-world value?","opts":["Having the single most sophisticated tool on the market","Switching frequently between many different tools","The tool's price alone","Consistent daily use rather than an extensive feature set"],"correct":3,"exp":"A simple tool used reliably tends to outperform a more advanced one that is used inconsistently or abandoned."},{"q":"What is a downside of constantly switching between many productivity tools?","opts":["It causes confusion and scattered, inconsistent systems","It always improves organisation immediately","There is no downside to switching frequently","It guarantees better task tracking"],"correct":0,"exp":"Frequent switching prevents any one system from being used consistently, undermining the organisation it is meant to provide."},{"q":"A team adopts several tools that duplicate work and fragment information. What should be evaluated?","opts":["Only the number of subscriptions","Only the newest feature names","Whether the tools support an integrated useful workflow","Only their app icons"],"correct":2,"exp":"Productivity tools should reduce practical friction."}]},
    {"key":"M14:Cybersecurity Basics","rows":[{"q":"What do cybersecurity basics cover?","opts":["A type of marketing strategy","Practical steps to protect digital information from unauthorised access, loss, or theft","Only protecting physical office equipment","Only relevant for large technology companies"],"correct":1,"exp":"Cybersecurity focuses on safeguarding a business's digital data and systems, which even small businesses possess and must protect."},{"q":"What is one simple, effective cybersecurity practice?","opts":["Avoiding any caution with unexpected links or attachments","Reusing the same password across every account","Using strong, unique passwords and backing up data regularly","Sharing sensitive information with anyone who asks"],"correct":2,"exp":"Unique, strong passwords and regular backups are simple, effective habits that meaningfully reduce common security risks."},{"q":"Why do even small businesses need to consider cybersecurity?","opts":["Cybersecurity is only a legal requirement for large companies","Small businesses are automatically immune to security incidents","They typically hold no valuable data at all","They often hold data, like customer information, that is valuable enough to be targeted"],"correct":3,"exp":"Even a small business commonly stores customer and financial data valuable enough to attract unauthorised access attempts."},{"q":"A founder gives every staff member the same administrator password. What should improve?","opts":["Individual accounts, appropriate permissions and strong authentication","Only the password's file name","Only the website's logo","Only a longer account label"],"correct":0,"exp":"Account separation and limited privileges support security and accountability."}]},
    {"key":"M15:Professional Communication","rows":[{"q":"What does professional communication shape?","opts":["How seriously a business is perceived, beyond product quality alone","Only the price of a business's products","Only a business's tax obligations","Nothing of real significance"],"correct":0,"exp":"Communication quality influences how credible and trustworthy a business appears, independent of its actual product."},{"q":"How should tone adapt across different professional relationships?","opts":["It should always remain identical regardless of context","It should adapt to the relationship and context while staying clear and respectful","Formal messages should always be used for every relationship","Tone has no relevance to professional communication"],"correct":1,"exp":"Appropriate tone shifts with context and relationship, but clarity and respect should remain constant."},{"q":"What can careless communication errors do to a business relationship?","opts":["They only matter for very large companies","They have no real effect on how a business is perceived","They can quietly undermine credibility and trust","They always strengthen a business relationship"],"correct":2,"exp":"Sloppy or careless communication can raise doubts about a business's reliability, even when the underlying product is strong."},{"q":"A business update is polite but leaves the recipient unsure what to do next. What should improve?","opts":["Only the email signature's size","Only the number of formal phrases","Only a longer greeting","The purpose, relevant information and clear requested action"],"correct":3,"exp":"Professional communication should make the intended next step clear."}]},
    {"key":"M15:Business Writing","rows":[{"q":"What should business writing prioritise above all else?","opts":["Using the most complex language available","Writing as long a message as possible","Avoiding stating any clear action needed","Clarity and a clear purpose"],"correct":3,"exp":"Clear, purposeful writing helps the reader understand the message and act on it quickly, which is the core goal of business writing."},{"q":"What tends to happen with unnecessarily complex language?","opts":["It tends to obscure meaning rather than communicate it clearly","It has no effect on how a message is understood","It speeds up the reader's understanding","It always demonstrates greater competence"],"correct":0,"exp":"Overly complex wording tends to slow down and confuse the reader rather than showcase genuine expertise."},{"q":"What helps a reader quickly follow a written business message?","opts":["Making the message as long and detailed as possible","A logical structure covering what, why, and what happens next","Randomly ordering the information","Leaving out the purpose of the message entirely"],"correct":1,"exp":"A clear, logical structure lets the reader quickly grasp the message's purpose and any required action."},{"q":"A proposal uses vague claims and unexplained technical jargon. What should be revised?","opts":["Only a more elaborate cover","Only additional buzzwords","Only the file extension","Clear specific language suited to its reader"],"correct":3,"exp":"Business writing should support understanding and decisions."}]},
    {"key":"M15:Email Communication","rows":[{"q":"What helps a recipient prioritise an email before opening it?","opts":["Leaving the subject line blank","The email's font style","A clear, informative subject line","A very long subject line with excessive detail"],"correct":2,"exp":"A clear subject line lets a recipient quickly understand and prioritise the email's content and urgency."},{"q":"Where should the most important information in an email be placed?","opts":["It does not matter where information is placed","Only in an attachment, never in the email body","Buried at the very end, after extensive background","Near the start, so it is not missed if the reader skims"],"correct":3,"exp":"Placing key information early ensures it is seen even by a reader who only skims the message quickly."},{"q":"What can happen if an email's actual request is buried deep in the message?","opts":["The recipient may miss it entirely and fail to act on it","It always guarantees a faster response","It has no effect on whether the recipient responds","It makes the email more professional"],"correct":0,"exp":"A request that is hard to find within a long message risks being overlooked, resulting in no action being taken."},{"q":"An email requests urgent approval but does not identify the document version. What should be included?","opts":["Only more recipients unrelated to the decision","The relevant version, decision and deadline","Only a larger signature image","Only a motivational quote"],"correct":1,"exp":"Email requests need enough context for a correct response."}]},
    {"key":"M15:Proposal Writing","rows":[{"q":"What does a strong business proposal clearly state?","opts":["Nothing specific; general language is preferred","The problem, proposed solution, terms, and why this business is the right choice","Only the price, with no other details","Only the founder's personal background"],"correct":1,"exp":"A strong proposal covers the key elements a recipient needs to evaluate and act on the specific opportunity."},{"q":"Why does tailoring a proposal to the specific recipient matter?","opts":["Generic templates always perform better","Recipients never notice whether a proposal is tailored","A tailored proposal is far more persuasive than a generic, one-size-fits-all template","Tailoring a proposal has no effect on its persuasiveness"],"correct":2,"exp":"Demonstrating specific understanding of the recipient's actual situation makes a proposal noticeably more compelling."},{"q":"What builds more credibility in a proposal than vague promises?","opts":["Using as much generic language as possible","Avoiding any specific numbers or dates","Making the proposal as short as possible with no detail","Concrete details like costs, timelines, and deliverables"],"correct":3,"exp":"Specific, concrete details give a recipient real information to evaluate, building more trust than vague assurances."},{"q":"A business proposal promises services without quantities, timing or price assumptions. What should be defined?","opts":["Only a more colourful title","Only the founder's portrait","The concrete scope, deliverables and commercial terms","Only the organisation's slogan"],"correct":2,"exp":"A proposal should make the planned engagement reviewable."}]},
    {"key":"M15:Presentation Skills","rows":[{"q":"What is the goal of most business presentations?","opts":["To move the audience toward a specific understanding or decision","To include as much detail as possible","To avoid ever being asked questions","Only to fill the allotted time"],"correct":0,"exp":"A presentation typically aims to inform and persuade an audience toward a clear understanding or decision, not simply to present information."},{"q":"What tends to make a presentation more effective?","opts":["Overwhelming the audience with dense detail on every slide","A few clear key points supported by simple visuals and concrete examples","Avoiding any structure at all","Reading the slides word for word without preparation"],"correct":1,"exp":"Focused key points with simple support material help an audience follow and retain the message more effectively than dense detail."},{"q":"Why does practising a presentation in advance help?","opts":["It guarantees the audience will ask no questions","It is only useful for very long presentations","It builds confidence that keeps delivery clear even under pressure or unexpected questions","Practising has no effect on presentation quality"],"correct":2,"exp":"Rehearsing in advance helps a presenter stay composed and clear, even when faced with pressure or unanticipated questions."},{"q":"A presentation contains dense slides that compete with the speaker. What should improve?","opts":["Add every spoken sentence to each slide","Use smaller text throughout","Read the file name repeatedly","A focused structure with clear supporting visuals"],"correct":3,"exp":"Slides should support the audience's understanding of the message."}]},
    {"key":"M15:Networking","rows":[{"q":"What is networking?","opts":["Simply collecting as many business cards as possible","A type of financial transaction","A marketing advertisement","Deliberately building and maintaining professional relationships that can create opportunities over time"],"correct":3,"exp":"Networking is the ongoing, deliberate cultivation of professional relationships, not a one-time collection of contacts."},{"q":"What tends to build stronger professional relationships?","opts":["Genuine interest and reciprocity, including offering help without immediate expectation of return","Avoiding any follow-up after an initial meeting","Collecting contacts without ever engaging further","Treating every interaction as purely transactional"],"correct":0,"exp":"Authentic engagement and reciprocity, rather than purely transactional behaviour, tend to build more durable relationships."},{"q":"What matters more for networking's real value?","opts":["The sheer number of contacts collected","The genuineness and maintenance of the relationships built","Avoiding any personal engagement with contacts","Only networking with people in the exact same industry"],"correct":1,"exp":"A smaller number of genuinely maintained relationships tends to produce more real opportunity than a large, shallow contact list."},{"q":"A founder collects contacts without following up or understanding their needs. What would make networking more useful?","opts":["Only a larger contact count","Only a new business-card texture","Only more unsolicited identical pitches","Relevant relationships and purposeful follow-up"],"correct":3,"exp":"Networking gains value through useful ongoing relationships."}]},
    {"key":"M15:Public Speaking","rows":[{"q":"Is public speaking a fixed trait some people simply have?","opts":["Only naturally confident people can ever speak publicly well","Yes, it cannot be improved with practice","No, it is a skill that can improve meaningfully with deliberate practice","Public speaking has no relevance to business"],"correct":2,"exp":"Public speaking ability can be genuinely developed through deliberate practice, rather than being a fixed, unchangeable trait."},{"q":"What matters more to an audience than perfectly polished delivery?","opts":["Speaking as quickly as possible","Covering as many ideas as possible in one talk","Avoiding any pauses whatsoever","Clarity and pacing that help the audience actually absorb the message"],"correct":3,"exp":"Clear, well-paced speech that the audience can follow matters more than flawless, rapid delivery."},{"q":"What can practising in front of a small, low-stakes audience first help with?","opts":["Building confidence before delivering the same talk to a larger audience","It has no benefit at all","It guarantees the larger audience will ask no questions","It replaces the need to ever prepare content"],"correct":0,"exp":"A low-stakes practice run helps build the confidence and refine the delivery needed for a larger, higher-stakes audience."},{"q":"A speaker loses the audience in an unstructured list of details. What should guide preparation?","opts":["Only a louder microphone","Only a longer biography","Only more slide transitions","A clear audience-focused message and logical sequence"],"correct":3,"exp":"Public speaking needs a coherent message people can follow."}]},
    {"key":"M15:Negotiation","rows":[{"q":"What is the goal of negotiation in business communication?","opts":["Ending the relationship as quickly as possible","An agreement acceptable to everyone involved","Ensuring one side wins completely at the other's expense","Avoiding any actual discussion of terms"],"correct":1,"exp":"Effective negotiation seeks a mutually acceptable outcome, not a one-sided victory."},{"q":"Why does written negotiation require particular care?","opts":["Written negotiation has no real risk of misunderstanding","Writing removes the need for courtesy","Tone can be easily misread without the context of voice or facial expression","Written communication is always clearer than spoken communication"],"correct":2,"exp":"Without vocal tone or facial cues, written messages can come across more harshly than intended, so extra clarity and courtesy help."},{"q":"What helps prevent future misunderstandings after a negotiation?","opts":["Relying only on memory of a verbal agreement","Avoiding any written record of what was agreed","Assuming both sides remember the same details","Confirming the agreed terms in writing afterward"],"correct":3,"exp":"A written confirmation of agreed terms creates a clear, shared record that reduces the risk of later disputes."},{"q":"Two parties argue over price while delivery timing matters more to one of them. What should be explored?","opts":["Only repeating the original positions","Their underlying interests and possible trade-offs","Only a stronger sales slogan","Only the room's seating arrangement"],"correct":1,"exp":"Negotiation can uncover terms that address different priorities."}]},
    {"key":"M16:Executive Summary","rows":[{"q":"What is an executive summary?","opts":["A brief overview at the start of a business plan summarising the business and key request","A detailed financial appendix","A legal contract","A marketing advertisement"],"correct":0,"exp":"It is a concise summary placed at the start of the plan, covering the business, opportunity, and key ask."},{"q":"Why is an executive summary often especially important?","opts":["It replaces the need for the rest of the plan entirely","It may be the only section some busy readers read in full","It is always ignored by every reader","It has no bearing on whether the rest of the plan is read"],"correct":1,"exp":"Given limited time, many readers rely heavily on the executive summary, sometimes without reading further."},{"q":"When should the executive summary typically be written?","opts":["It does not matter when it is written","Only after the business has already launched","Last, after the rest of the plan is complete","First, before any other section is written"],"correct":2,"exp":"Writing it last allows the summary to accurately reflect the finished plan's most important and compelling points."},{"q":"A business plan's summary lists ambitions but omits the offer and evidence. What should be added?","opts":["Only a longer founder biography","Only more promotional adjectives","A concise account of the opportunity, model and supporting facts","Only decorative charts"],"correct":2,"exp":"An executive summary should convey the core business case."}]},
    {"key":"M16:Company Description","rows":[{"q":"What does the company description explain?","opts":["Only the business's financial projections","Only the founder's personal biography","Only the legal structure of the business","What the business is, does, its mission, and what makes it distinct"],"correct":3,"exp":"This section gives a grounded account of the business itself, its purpose, and its distinctiveness."},{"q":"What weakens a company description?","opts":["Vague, generic language that could describe almost any business","Specific, concrete details about the actual problem and customers","Explaining the business's mission clearly","Describing what makes the business distinct"],"correct":0,"exp":"Generic, non-specific language fails to convey what genuinely distinguishes the business."},{"q":"What makes a company description meaningful to a reader?","opts":["Making the description as short as a single sentence with no detail","Concrete, specific details about the real problem solved and real customers served","Using as many impressive-sounding but vague words as possible","Avoiding any mention of the business's mission"],"correct":1,"exp":"Specific, grounded details help a reader genuinely understand what makes the business distinct and worth attention."},{"q":"A company description provides history but no purpose or operating focus. What should be clarified?","opts":["Only the logo's colour values","Only office furniture details","What the company does, whom it serves and its current position","Only unrelated awards"],"correct":2,"exp":"Readers need a clear description of the actual business."}]},
    {"key":"M16:Market Analysis","rows":[{"q":"What does the market analysis section present?","opts":["Only the business's financial statements","A list of the business's employees","Evidence-based understanding of the target market's size, trends, segments, and competition","Only the founder's personal opinion of the market"],"correct":2,"exp":"This section grounds claims about demand in real research covering market size, trends, and competition."},{"q":"What makes a market analysis more credible?","opts":["Avoiding any mention of competitors","Vague, general statements with no sources","Sweeping, unsupported claims about market size","Real, checkable evidence like actual data or direct customer research"],"correct":3,"exp":"Concrete, verifiable evidence is far more persuasive and credible than broad, unsupported assertions."},{"q":"Why can a weak market analysis undermine the rest of a business plan?","opts":["It can cause a skeptical reader to question the credibility of the plan's other figures too","It has no effect on how the rest of the plan is perceived","A weak market analysis always increases investor confidence","Market analysis is unrelated to other sections of the plan"],"correct":0,"exp":"If market assumptions appear ungrounded, a reader may extend that skepticism to the plan's other projections as well."},{"q":"A plan uses total population as proof of its reachable market. What should be estimated?","opts":["The relevant segment, access constraints and supporting evidence","Only the largest possible headline figure","Only a competitor's slogan","Only the founder's expected followers"],"correct":0,"exp":"A useful market analysis distinguishes broad population from reachable demand."}]},
    {"key":"M16:Products & Services","rows":[{"q":"What should the products and services section describe?","opts":["Only the legal structure of the business","Exactly what the business offers, how it works, and what problem it addresses","Only the business's financial history","Only the founder's personal background"],"correct":1,"exp":"This section explains the actual offer, its mechanics, and the specific customer problem it solves."},{"q":"What matters more to most readers than technical features alone?","opts":["The founder's personal preferences","The number of employees involved in production","The customer benefit the product or service actually delivers","The exact manufacturing process used"],"correct":2,"exp":"Readers, whether investors or customers, are typically more interested in what an offer does for them than raw technical detail."},{"q":"Why should this section be detailed enough for an unfamiliar reader?","opts":["Detail has no effect on a reader's understanding","Unfamiliar readers should be discouraged from understanding the offer","This section is only meant for existing customers","So they can understand exactly what is being sold without prior knowledge of the business"],"correct":3,"exp":"Sufficient detail ensures that even a reader new to the business can clearly grasp what is actually being offered."},{"q":"A plan describes a product's technology without explaining its use. What should be connected?","opts":["Only additional technical acronyms","Only the product's colour","The offer's benefits and the customer's problem","Only a longer product name"],"correct":2,"exp":"The offer should explain the value delivered to customers."}]},
    {"key":"M16:Marketing Plan","rows":[{"q":"What does a marketing plan translate general strategy into?","opts":["Specific channels, messages, budget, and expected results","A list of the founder's personal opinions","Only a company's legal structure","Only a description of the product itself"],"correct":0,"exp":"The marketing plan makes strategy concrete and actionable through specific channels, messaging, budget, and expected outcomes."},{"q":"What makes a marketing plan more credible to a reader?","opts":["Listing every possible marketing channel regardless of relevance","Being realistic and specific to the actual target customer already identified","Avoiding any mention of budget","Avoiding any expected results or metrics"],"correct":1,"exp":"Focus on channels genuinely relevant to the actual target customer signals a realistic, well-considered plan."},{"q":"What can listing every possible marketing channel signal to a reader?","opts":["Guaranteed marketing success","Nothing meaningful about the plan's quality","A lack of real focus and realism in the plan","Strong, credible strategic thinking"],"correct":2,"exp":"An unfocused list of every conceivable channel, without regard for actual customer fit, can undermine a plan's credibility."},{"q":"A marketing plan names channels without goals, budget or measurement. What should be added?","opts":["Only more channel names","Audience, objectives, actions, resources and outcome measures","Only a decorative campaign calendar","Only the logo's dimensions"],"correct":1,"exp":"A usable plan links activity to a defined purpose and resources."}]},
    {"key":"M16:Operations Plan","rows":[{"q":"What does the operations plan explain?","opts":["Only the business's marketing strategy","Only the founder's personal biography","Only the business's tax obligations","The practical, day-to-day workings of how the business produces and delivers its offer"],"correct":3,"exp":"This section addresses the concrete logistics of running the business, complementing the plan's strategic sections."},{"q":"What should a credible operations plan identify?","opts":["Key logistical requirements like suppliers, staffing, equipment, and location","Only the founder's personal opinions","Only competitor pricing","Only the executive summary's key points"],"correct":0,"exp":"Identifying concrete logistical needs demonstrates real, practical planning behind the business's ambitions."},{"q":"Why does a strong operations plan matter to a reader?","opts":["It is only relevant for very large businesses","It shows the founder has thought through practical realities, not just financial or marketing potential","It has no bearing on how a reader evaluates the plan","It replaces the need for a financial plan"],"correct":1,"exp":"Demonstrating practical operational readiness reassures a reader that the business's ambitions are grounded in real capability."},{"q":"Projected sales exceed the venture's production capacity. What should the operations plan reconcile?","opts":["Only the sales chart's colour","Only the business name","Only the website's font","Demand assumptions with people, process and resource capacity"],"correct":3,"exp":"The plan must explain how the promised output can be delivered."}]},
    {"key":"M16:Financial Plan","rows":[{"q":"What does the financial plan section present?","opts":["Only the business's marketing slogans","Only a description of the product","The numbers behind the business: costs, revenue projections, expenses, and cash flow","Only the founder's personal financial history"],"correct":2,"exp":"This section translates the plan's claims into specific financial figures a reader can evaluate."},{"q":"What makes a financial plan more credible?","opts":["Presenting impressive numbers disconnected from the rest of the plan","Avoiding any explanation of underlying assumptions","Using figures unrelated to the market or marketing plan","Being grounded in the same assumptions used in the plan's other sections"],"correct":3,"exp":"Consistency between the financial figures and the assumptions described elsewhere in the plan builds credibility."},{"q":"What can disconnected, unexplained financial projections cause?","opts":["Doubt in a careful reader about where the numbers actually came from","No effect on how the plan is received","Guaranteed funding regardless of other content","Increased investor confidence automatically"],"correct":0,"exp":"Numbers that do not connect logically to the rest of the plan can raise skepticism about their basis and reliability."},{"q":"The financial plan predicts profit but contains no cash timing. What is missing?","opts":["A cash forecast linked to receipts, payments and funding needs","Only a larger net-profit figure","Only a new invoice design","Only more sales slogans"],"correct":0,"exp":"Profit projections alone do not establish cash availability."}]},
    {"key":"M16:Risk Analysis","rows":[{"q":"What does a risk analysis section identify?","opts":["Only competitor weaknesses","Specific, realistic risks the business faces and how it plans to address them","Only the business's strengths","Only the founder's personal achievements"],"correct":1,"exp":"This section honestly names real risks and describes a credible plan for addressing each."},{"q":"What can omitting a risk analysis, or offering only vague reassurance, do?","opts":["Have no effect on how a plan is received","Guarantee funding regardless of actual risk","Make experienced readers more skeptical, reading the plan as naive","Always increase investor confidence"],"correct":2,"exp":"Experienced readers expect real risks in any business; ignoring them can come across as naive rather than reassuring."},{"q":"What is more convincing than general optimism in a risk analysis?","opts":["Vague statements that nothing could go wrong","Avoiding any mention of risk entirely","Focusing only on the business's strengths","Specific mitigation plans for each identified risk"],"correct":3,"exp":"Concrete, specific plans for addressing named risks demonstrate real preparedness, which is more persuasive than blanket optimism."},{"q":"A business plan states that no major risks exist. What should be done?","opts":["Only remove the risk section","Assess plausible uncertainties, impact and planned responses","Only use stronger optimistic language","Only enlarge the opportunity section"],"correct":1,"exp":"Planning should acknowledge and prepare for material uncertainty."}]},
    {"key":"M16:Exit Strategy","rows":[{"q":"What does an exit strategy describe?","opts":["How a founder or investor might eventually realise the value built in the business","Only how to close the business immediately","Only the founder's personal retirement plans","A type of daily operations checklist"],"correct":0,"exp":"It outlines the eventual path &mdash; sale, acquisition, public offering, or sustained profit &mdash; to realising the business's built value."},{"q":"Why is an exit strategy especially relevant when outside investors are involved?","opts":["It replaces the need for a financial plan","Investors typically need some path to eventually recover and profit from their investment","Outside investors never care about exit strategy","It is only relevant for businesses with no outside investors"],"correct":1,"exp":"Since investors seek an eventual return, addressing how they might realise it matters directly to their confidence in the plan."},{"q":"What does including a thoughtful exit strategy signal to a reader?","opts":["That the business has no long-term viability","Nothing of relevance to an investor","Long-term thinking beyond just the immediate startup phase","That the founder intends to close the business immediately"],"correct":2,"exp":"A considered exit strategy shows the founder has thought about the business's full trajectory, which can build investor confidence."},{"q":"A founder describes selling the venture as a guaranteed future outcome. What should be recognised?","opts":["Every business can be sold at any chosen price","An exit removes all current obligations","Exit options depend on conditions and should remain assumptions","A logo guarantees buyer interest"],"correct":2,"exp":"Exit planning considers possibilities rather than assured results."}]},
    {"key":"M16:Writing a Complete Business Plan","rows":[{"q":"What does writing a complete business plan involve?","opts":["Writing only the executive summary","Writing each section with no regard for the others","Skipping the financial plan entirely","Bringing every individual section together into one coherent, consistent document"],"correct":3,"exp":"A complete plan integrates every section &mdash; from summary to exit strategy &mdash; into one unified, consistent document."},{"q":"What is a common weakness in a finished business plan?","opts":["Internal inconsistency between different sections","Too much consistency between sections","Including a risk analysis section","Writing the executive summary last"],"correct":0,"exp":"Mismatched assumptions or figures across sections are a frequent, avoidable flaw in finished business plans."},{"q":"What helps catch inconsistencies before a reader does?","opts":["Skipping the review process to save time","A final, careful review checking every section against every other section","Submitting the plan without ever reviewing it","Writing every section in complete isolation with no later review"],"correct":1,"exp":"A thorough final review of the whole document helps identify and fix inconsistencies before the plan reaches a reader."},{"q":"Different sections of a business plan use incompatible sales and staffing assumptions. What must be reconciled?","opts":["Only the cover's layout","Only the table of contents font","The connections between market, operations and financial projections","Only the document's filename"],"correct":2,"exp":"A complete plan needs internally consistent assumptions."}]},
    {"key":"M17:Launch Strategy","rows":[{"q":"What is a launch strategy?","opts":["A type of financial loan","A legal registration requirement","A deliberate plan sequencing the specific actions needed to introduce a business to the market","Only picking an opening date"],"correct":2,"exp":"A launch strategy goes beyond a date, deliberately planning the sequence of actions for entering the market."},{"q":"What is an advantage of a smaller, controlled soft launch before a full launch?","opts":["It guarantees no problems will ever occur","It has no advantage over a full launch","It always costs more than a full launch","It lets early problems surface and be fixed while stakes and audience are still small"],"correct":3,"exp":"A soft launch limits early exposure, allowing issues to be caught and corrected before a wider rollout."},{"q":"What risk comes from rushing straight to a full, wide launch?","opts":["Missing the chance to catch and fix mistakes while they are still small and manageable","There is no risk at all","It guarantees a smoother launch than a staged approach","It eliminates the need for a marketing plan"],"correct":0,"exp":"A full launch without a smaller test phase risks an unaddressed problem affecting the entire market audience at once."},{"q":"A launch strategy targets several audiences with conflicting needs. What should be prioritised?","opts":["Only the biggest possible announcement","Only a wider set of slogans","A defined initial segment and clear launch objective","Only more launch-day photographs"],"correct":2,"exp":"A focused launch makes learning and execution more manageable."}]},
    {"key":"M17:Product Launch","rows":[{"q":"What does a product launch involve?","opts":["Only a legal registration filing","Coordinated marketing, sales readiness, and operational preparation, aligned together","Only a marketing advertisement","Only a financial forecast"],"correct":1,"exp":"A launch requires marketing, sales, and operations to be ready and aligned at the same time."},{"q":"What risk comes from launching before operations can support real demand?","opts":["It always improves the launch's momentum","It guarantees stronger long-term sales","Disappointing early customers who could have driven positive word-of-mouth","No risk; operations readiness has no bearing on launch success"],"correct":2,"exp":"Early customers who have a poor experience due to operational shortfalls can undermine the momentum a launch depends on."},{"q":"Why are early customers especially important during a launch?","opts":["Early customers have no influence on other potential buyers","Early customers are always guaranteed to be satisfied","Early customer experience has no bearing on business success","Their experience often shapes word-of-mouth that influences the wider launch's momentum"],"correct":3,"exp":"Because early customers can strongly influence word-of-mouth, their experience matters disproportionately to a launch's success."},{"q":"Paid orders begin before the product meets the promised specification. What should be assessed?","opts":["Delivery readiness and accurate customer commitments","Only the celebration's decorations","Only the founder's speech","Only a larger signup target"],"correct":0,"exp":"Launch commitments should match actual delivery capability."}]},
    {"key":"M17:Marketing Campaign","rows":[{"q":"What defines a marketing campaign?","opts":["A focused, time-bound set of activities built around a specific goal","Ongoing, general marketing activity with no specific goal","A type of legal registration","A financial forecasting method"],"correct":0,"exp":"A campaign is distinguished by its focus, time-bound nature, and connection to a specific objective, unlike general ongoing marketing."},{"q":"What makes a marketing campaign effective?","opts":["A different message on every channel used","A clear, singular core message repeated consistently across every channel","Avoiding any measurable objective","Running indefinitely with no defined end"],"correct":1,"exp":"Consistency of message across channels helps it stick in a customer's mind more effectively than scattered, varied messaging."},{"q":"Why should a campaign have measurable objectives?","opts":["Measurable objectives are only relevant for large companies","To make the campaign more expensive","So a founder can judge whether the campaign is actually working","Objectives have no real use for a campaign"],"correct":2,"exp":"Clear, measurable objectives let a founder evaluate the campaign's actual effectiveness and inform future campaigns."},{"q":"A launch campaign has traffic goals but no link to qualified customer action. What should be measured?","opts":["Only total image views","Only the campaign's filename","Only the number of published posts","The relevant conversion and customer outcomes"],"correct":3,"exp":"Campaign success should be connected to its intended business outcome."}]},
    {"key":"M17:Sales Launch","rows":[{"q":"What does a sales launch focus on?","opts":["Only generating attention through advertising","Only the business's financial plan","Only legal registration for the launch","Preparing the sales process to convert marketing-generated attention into actual sales"],"correct":3,"exp":"A sales launch ensures the sales side is ready to convert the interest a launch's marketing generates."},{"q":"What common launch mistake involves marketing and sales?","opts":["Investing heavily in marketing while leaving the sales process underprepared","Preparing the sales team too thoroughly","Avoiding any marketing altogether","There is no common mistake involving marketing and sales together"],"correct":0,"exp":"A frequent launch problem is generating strong interest through marketing without a sales process ready to convert it."},{"q":"What helps a sales team convert interest confidently during a launch?","opts":["Relying only on marketing to close every sale","Rehearsing likely customer questions and objections in advance","Avoiding any preparation before the launch","Ignoring customer objections entirely"],"correct":1,"exp":"Preparing for likely questions and objections in advance builds the confidence needed to convert interest into sales."},{"q":"The sales team starts outreach without knowing the approved offer. What is needed?","opts":["Only more sales calls","Only a louder pitch","Only the founder's signature","Consistent product, pricing and fulfilment information"],"correct":3,"exp":"A sales launch needs clear usable information and commitments."}]},
    {"key":"M17:Customer Support","rows":[{"q":"Why does customer support matter especially during and right after a launch?","opts":["Support only matters after a business has been running for years","Early customers never need any support","A new customer's first interaction strongly shapes whether they return or recommend the business","Customer support has no real impact during a launch"],"correct":2,"exp":"Because first impressions carry outsized weight, early support quality strongly influences long-term customer relationships."},{"q":"What reduces the risk of a poor first support experience?","opts":["Waiting until problems arise to prepare any answers","Ignoring customer questions during launch","Assuming no customer will ever have questions","Anticipating and preparing for common early customer questions before launch"],"correct":3,"exp":"Proactively preparing for likely early questions helps ensure a smoother, more confident support experience from day one."},{"q":"What can a fast, helpful response to early launch issues achieve?","opts":["Turn a rocky start into lasting customer loyalty","Guarantee no future customer issues will ever occur","Have no effect on customer perception","Always increase support costs unnecessarily"],"correct":0,"exp":"Responding well to early problems can build trust and loyalty, even when the initial experience started roughly."},{"q":"A launch attracts users but nobody owns incoming support requests. What should be established?","opts":["Only a welcome banner","Only an automatic message claiming everything is solved","Only the product's nickname","Channels, responsibilities and response procedures"],"correct":3,"exp":"Support needs a practical way to receive and resolve issues."}]},
    {"key":"M17:Measuring Success","rows":[{"q":"What does measuring success require?","opts":["Always declaring the effort a success regardless of outcome","Defining specific numbers indicating success, set before the launch or effort begins","Judging success only afterward based on a general feeling","Avoiding any specific metrics"],"correct":1,"exp":"Predefined, specific measures allow an honest, objective evaluation of whether an effort actually succeeded."},{"q":"What trap do predefined success measures help prevent?","opts":["Learning from past launches","Setting overly ambitious goals","Unconsciously shifting the definition of success after the fact to match the actual result","Having any measurable objectives at all"],"correct":2,"exp":"Without a fixed standard set in advance, it is easy to unconsciously redefine success to match whatever actually happened."},{"q":"Why does defining success in advance matter for future decisions?","opts":["It has no bearing on future planning","It guarantees future launches will always succeed","It eliminates the need for any further measurement","It allows honest evaluation of what worked, informing how future efforts should be adjusted"],"correct":3,"exp":"Honest evaluation against a predefined standard provides real, useful lessons for improving future efforts."},{"q":"A launch is declared successful solely because many people visited its page. What else should be evaluated?","opts":["Only the largest visitor figure","Only the number of launch photographs","The defined customer, conversion and operational outcomes","Only the founder's confidence"],"correct":2,"exp":"Success must be assessed against meaningful objectives."}]},
    {"key":"M17:Growth Planning","rows":[{"q":"What is growth planning?","opts":["The deliberate process of deciding how a business will expand once its initial offer has proven successful","A type of financial loan","A legal registration requirement","A marketing slogan"],"correct":0,"exp":"Growth planning intentionally decides the direction and pace of expansion based on what has been proven to work."},{"q":"What tends to make growth more sustainable?","opts":["Avoiding any planning at all","Deliberate, evidence-based planning matched to what has actually proven to work","Reactively chasing every opportunity that appears, regardless of readiness","Expanding without regard for operational capacity"],"correct":1,"exp":"Growth grounded in real evidence and matched to actual capacity tends to be more sustainable than purely reactive expansion."},{"q":"What can happen if growth outpaces actual operational capacity?","opts":["Operational capacity has no relationship to growth outcomes","Nothing; capacity is irrelevant to growth planning","Quality can suffer as the business struggles to support the expanded scale","Quality always improves automatically with faster growth"],"correct":2,"exp":"Expanding faster than operations can support risks quality problems across the business, undermining the growth itself."},{"q":"A founder plans expansion without checking retention or cash requirements. What should come first?","opts":["Only a larger office","Only a new growth slogan","Only another investor slide","Evidence of sustainable demand and operational funding capacity"],"correct":3,"exp":"Growth planning should test the foundations that expansion depends on."}]},
    {"key":"M17:Scaling the Business","rows":[{"q":"What does scaling a business mean?","opts":["Growing revenue and costs at exactly the same proportional rate always","A type of legal registration","A financial loan process","Growing revenue and reach significantly, ideally without costs growing at the same rate"],"correct":3,"exp":"Scaling aims for revenue and reach to grow substantially faster than costs, typically through repeatable systems."},{"q":"What usually makes scaling possible?","opts":["Repeatable systems, processes, and sometimes technology","The founder personally handling every single transaction","Avoiding any documentation of processes","Reducing customer demand"],"correct":0,"exp":"Systems and processes that do not depend entirely on one person let a business serve more customers without proportional added effort."},{"q":"What can limit a business's ability to scale?","opts":["Strong, proven customer demand","Dependence entirely on the founder's personal, unrepeatable involvement in every transaction","Having well-documented, repeatable systems","Using technology to remove bottlenecks"],"correct":1,"exp":"If growth requires the founder's direct, personal involvement in every transaction, that dependency becomes a hard limit on scaling."},{"q":"Order volume doubles while quality collapses. What needs strengthening?","opts":["Processes, capacity and controls that preserve delivery standards","Only the advertising budget","Only the company's logo","Only the revenue chart's height"],"correct":0,"exp":"Scaling should support greater volume without destroying value."}]},
    {"key":"M18:Scaling Operations","rows":[{"q":"What does scaling operations involve?","opts":["Only expanding into new international markets","A type of financial loan","Adapting staffing, processes, technology, and facilities to reliably support more volume","Only increasing marketing spend"],"correct":2,"exp":"Operational scaling adapts the practical workings of a business to handle greater volume without breaking down."},{"q":"What common mistake occurs when scaling a business?","opts":["Scaling operations before increasing marketing at all","Testing systems before pursuing growth","There is no common mistake in scaling","Scaling marketing and sales faster than operations can support"],"correct":3,"exp":"Generating more demand than operations can actually fulfil well is a frequent, damaging scaling mistake."},{"q":"What can happen if growth outpaces operational readiness?","opts":["Quality and reputation can suffer as the business struggles to keep up","Quality always improves automatically","It has no effect on the business's reputation","Operational readiness has no bearing on growth outcomes"],"correct":0,"exp":"When operations cannot keep pace with growing demand, the resulting quality problems can damage the business's reputation."},{"q":"A venture scales a process that already creates frequent errors. What should precede expansion?","opts":["Hire more people to repeat the errors","Hide customer complaints","Only rename the department","Improve the process and verify reliable performance"],"correct":3,"exp":"Expanding an unreliable process multiplies its weaknesses."}]},
    {"key":"M18:Expansion Strategies","rows":[{"q":"What are expansion strategies?","opts":["A single, universal approach used identically by every business","Deliberate approaches for growing a business's reach, such as new locations, products, or markets","Only ways to reduce a business's costs","A type of legal business structure"],"correct":1,"exp":"Expansion strategies cover the range of deliberate approaches &mdash; new locations, products, segments, or markets &mdash; for growing reach."},{"q":"What should guide the choice of expansion strategy?","opts":["Random selection with no evaluation","Only what competitors happen to be doing","The business's actual proven strengths and available resources","Whichever option sounds most ambitious, regardless of fit"],"correct":2,"exp":"Matching a strategy to what the business genuinely does well and can actually support tends to produce better results."},{"q":"What can happen when a business pursues too many expansion directions at once?","opts":["Success is guaranteed regardless of focus","It always improves overall efficiency","It has no effect on the business's chances of success","Resources become strained across unfamiliar directions, reducing the chance of success in any of them"],"correct":3,"exp":"Spreading resources across too many new, unfamiliar directions at once often weakens the chance of succeeding in any single one."},{"q":"A profitable location is used to justify expansion into a very different market. What should be tested?","opts":["Only the original site's popularity","Only a matching shopfront colour","Only the founder's enthusiasm","Local demand, economics and operating requirements"],"correct":3,"exp":"A new market can have different conditions and needs."}]},
    {"key":"M18:Franchising","rows":[{"q":"What is franchising?","opts":["Licensing a brand, systems, and business model to independent operators who run their own locations","A type of government grant","A method of hiring employees directly","A financial forecasting technique"],"correct":0,"exp":"Franchising extends a proven model to independent operators, who run their own locations under the established brand and system."},{"q":"When does franchising work best?","opts":["Franchising timing has no bearing on its success","Once a business model is genuinely proven and clearly documented","Before the business model has been tested at all","Only for businesses with no established systems"],"correct":1,"exp":"A proven, well-documented model gives franchisees a reliable system to replicate, which is essential for franchising success."},{"q":"What happens when an unproven business is franchised?","opts":["Franchising always succeeds regardless of the underlying model","There is no effect on quality across locations","Its existing weaknesses tend to multiply across many new locations at once","Its weaknesses are automatically corrected through franchising"],"correct":2,"exp":"Franchising an unproven model spreads its existing flaws across multiple new locations rather than correcting them."},{"q":"A founder wants to franchise a business dependent on undocumented personal knowledge. What needs development?","opts":["A repeatable system, standards and appropriate legal arrangements","Only a larger sign","Only a new franchise slogan","Only the founder's biography"],"correct":0,"exp":"Franchising requires a reproducible business and clear agreements."}]},
    {"key":"M18:Partnerships","rows":[{"q":"What is a strategic business partnership?","opts":["A single business operating entirely alone","A type of government grant","A legal registration requirement","Two or more businesses combining complementary strengths to achieve more together"],"correct":3,"exp":"Partnerships combine distinct strengths from different businesses to accomplish something neither could as efficiently alone."},{"q":"What is essential for a partnership's success from the start?","opts":["Clearly defined roles, responsibilities, and shared expectations","Leaving every detail intentionally vague","Avoiding any written agreement","Ensuring both partners have identical strengths"],"correct":0,"exp":"Clarity about roles and expectations from the outset helps prevent the friction that ambiguity tends to cause as a partnership grows."},{"q":"What should a good strategic partner offer?","opts":["Only financial capital, with no other capability","Strengths that genuinely complement, rather than simply duplicate, your own","The exact same strengths and resources you already have","No specific value at all"],"correct":1,"exp":"A partnership works best when combined strengths are complementary, filling gaps rather than overlapping unnecessarily."},{"q":"Two ventures announce a partnership without defining contributions or decisions. What should be agreed?","opts":["Only the joint logo","Only the launch photograph","Roles, value exchange, responsibilities and governance","Only an informal shared slogan"],"correct":2,"exp":"A workable partnership requires clear practical terms."}]},
    {"key":"M18:International Expansion","rows":[{"q":"What additional complexity does international expansion introduce?","opts":["Only a change in the business's legal name","Only a change in product pricing","Different regulations, currencies, cultural expectations, and competitive landscapes","No additional complexity compared to domestic operations"],"correct":2,"exp":"Expanding internationally introduces distinct regulatory, cultural, currency, and competitive factors not present domestically."},{"q":"What is a common, costly mistake in international expansion?","opts":["Researching the target country's conditions thoroughly before expanding","Starting with just one well-researched country","Working with knowledgeable local partners or advisors","Assuming domestic success will automatically transfer without adapting to local differences"],"correct":3,"exp":"Failing to adapt a proven domestic approach to genuinely different local conditions is a frequent cause of international expansion failure."},{"q":"What reduces the overall risk of international expansion?","opts":["Starting with one well-researched country rather than many markets at once","Expanding into as many countries simultaneously as possible","Avoiding any local research or adaptation","Ignoring local regulations entirely"],"correct":0,"exp":"Focusing on one carefully researched market first limits exposure and allows lessons to inform any future expansion."},{"q":"A venture assumes its domestic permits cover a new country. What must be checked?","opts":["Only the existing business card","Only the original bank's logo","Only the founder's passport cover","The destination's applicable legal, market and operational requirements"],"correct":3,"exp":"Cross-border operations need destination-specific preparation."}]},
    {"key":"M18:Innovation Management","rows":[{"q":"What is innovation management?","opts":["A legal registration process","The deliberate process of encouraging, evaluating, and implementing new ideas within a business","Avoiding any new ideas to maintain stability","A type of financial forecasting method"],"correct":1,"exp":"Innovation management intentionally structures how new ideas are generated, assessed, and put into practice."},{"q":"What does effective innovation management balance?","opts":["Ignoring all new ideas from the team","Only accepting ideas from leadership","Openness to new ideas with disciplined evaluation of which to pursue","Pursuing every single idea equally with no evaluation"],"correct":2,"exp":"Good innovation management welcomes new ideas while applying a clear process to prioritise the most valuable ones."},{"q":"What can happen without a clear process for evaluating ideas?","opts":["Every idea automatically succeeds","Innovation always improves without any process needed","There is no effect on how ideas are pursued","Good ideas can be lost among many mediocre ones receiving equal attention"],"correct":3,"exp":"Without prioritisation, genuinely strong ideas can go unnoticed or under-resourced amid a flood of less valuable suggestions."},{"q":"A company funds every new idea without selection or learning criteria. What should improve?","opts":["Only the number of idea submissions","Only a more exciting meeting title","A process for evaluating, testing and deciding on innovations","Only the office's decorations"],"correct":2,"exp":"Innovation needs disciplined selection and evidence-led development."}]},
    {"key":"M18:Business Sustainability","rows":[{"q":"What does business sustainability mean?","opts":["Building a business that can continue reliably over the long term","Maximising short-term profit regardless of long-term consequences","A type of legal business structure","A marketing slogan with no real substance"],"correct":0,"exp":"Sustainability focuses on the business's ability to keep operating and creating value well into the future."},{"q":"What often happens to short-term gains that undermine long-term viability?","opts":["They are always the best choice for a business","They are not genuinely sustainable, however profitable they first appear","They always strengthen the business's long-term position","They have no bearing on long-term sustainability"],"correct":1,"exp":"Choices that boost short-term results at the expense of long-term health ultimately undermine the business's sustainability."},{"q":"How can sustainable practices benefit a business financially?","opts":["They have no financial relevance to a business","They only matter for very large corporations","They often align with real cost savings and reputation benefits over time","They always increase costs with no offsetting benefit"],"correct":2,"exp":"Practices like reducing waste or treating people well often produce genuine cost savings and reputational advantages over time."},{"q":"A venture grows sales while exhausting staff and losing money on every order. What should sustainability review include?","opts":["Only the sales growth percentage","Long-term financial, operational and people impacts","Only the company's new slogan","Only the number of new customers"],"correct":1,"exp":"Sustainability includes the capacity to keep delivering responsibly."}]},
    {"key":"M18:Exit Planning","rows":[{"q":"What is exit planning?","opts":["A type of marketing strategy","A legal registration requirement","A method for hiring new employees","Deliberately preparing for how and when a founder might eventually leave the business"],"correct":3,"exp":"Exit planning anticipates and prepares for the founder's eventual departure, through sale, transfer, or wind-down."},{"q":"When should good exit planning begin?","opts":["Well before an actual exit is imminent","Only once the founder has already decided to leave immediately","Exit planning never needs to begin in advance","Only after the business has already failed"],"correct":0,"exp":"Starting exit planning early allows time to build the systems and team that make any eventual exit smoother and more valuable."},{"q":"What increases a business's value and readiness for an eventual exit?","opts":["Having no plan at all for how the business might eventually change hands","Documented systems and a capable team not dependent entirely on the founder","Complete dependence on the founder's personal, undocumented involvement","Avoiding any financial record-keeping"],"correct":1,"exp":"Strong systems and an independent, capable team make a business more valuable and easier to transition, whatever form the exit takes."},{"q":"The founder is the only person who knows essential processes when a transition begins. What should be prepared?","opts":["Only a larger sale advertisement","Only the founder's portrait","Only a new business name","Documented operations, capable ownership and clear transition responsibilities"],"correct":3,"exp":"Continuity and transferable knowledge support a workable transition."}]}
  ];
  var topics = {}, practice = {};
  DATA.forEach(function(t) {
    topics[t.key] = t.rows.map(function(q) {return {q:q.q,opts:q.opts.slice(),correct:q.correct,exp:q.exp,module:Number(t.key.match(/^M(\d+):/)[1]),topic:t.key};});
    practice[t.key] = topics[t.key].slice(0,3);
  });
  window.TIH_ENTREPRENEURSHIP_QUESTIONS = {revision:2, topics:topics};
  window.TIH_TOPIC_QUIZZES = window.TIH_TOPIC_QUIZZES || {};
  window.TIH_TOPIC_QUIZZES.entrepreneurship = practice;
})();
